window.BIOMASTER = window.BIOMASTER || {};
window.BIOMASTER.MCQ_POPULATION = [{"id":"MCQ-PO-001","topic":"population","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Quần thể","q":"Quần thể nào sau đây đang ở trạng thái cân bằng di truyền Hardy - Weinberg?","opts":["$0.36 AA : 0.48 Aa : 0.16 aa$.","$0.49 AA : 0.40 Aa : 0.11 aa$.","$0.25 AA : 0.60 Aa : 0.15 aa$.","$0.70 AA : 0.20 Aa : 0.10 aa$."],"ans":0,"exp":"$0.36 \\times 0.16 = (0.48/2)^2 = 0.0576$."},{"id":"MCQ-PO-002","topic":"population","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Quần thể Tự phối","q":"Một quần thể thực vật tự thụ phấn có cấu trúc ban đầu $P: 0.4 AA : 0.4 Aa : 0.2 aa$. Tỉ lệ kiểu gen đồng hợp lặn ($aa$) ở thế hệ $F_2$ là:","opts":["$0.30$.","$0.25$.","$0.35$.","$0.55$."],"ans":2,"exp":"$Aa_{F2} = 0.4 \\times (1/4) = 0.10 \\Rightarrow aa_{F2} = 0.2 + \\frac{0.4 - 0.10}{2} = 0.35$."},{"id":"MCQ-PO-003","topic":"population","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Tần số alen","q":"Một quần thể cân bằng di truyền có tỉ lệ cá thể mang kiểu hình lặn ($aa$) chiếm $9\\%$. Tỉ lệ cá thể mang kiểu hình trội nhưng có kiểu gen dị hợp ($Aa$) trong quần thể là:","opts":["$91\\%$.","$49\\%$.","$42\\%$.","$21\\%$."],"ans":2,"exp":"$q^2 = 0.09 \\Rightarrow q = 0.3 ; p = 0.7 \\Rightarrow 2pq(Aa) = 2 \\times 0.7 \\times 0.3 = 0.42 = 42\\%$."},{"id":"MCQ-PO-004","topic":"population","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Nhân tố Tiến hóa","q":"Nhân tố tiến hóa nào sau đây là nhân tố DUY NHẤT có khả năng định hướng quá trình tiến hóa, quy định chiều hướng và nhịp điệu tích lũy các biến dị thích nghi?","opts":["Đột biến.","Các yếu tố ngẫu nhiên (Phiêu bạt di truyền).","Chọn lọc tự nhiên.","Giao phối không ngẫu nhiên."],"ans":2,"exp":"Chọn lọc tự nhiên là nhân tố tiến hóa có hướng duy nhất."},{"id":"MCQ-PO-005","topic":"population","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Bằng chứng Tiến hóa","q":"Cánh của chim và cánh của côn trùng (bướm), hoặc gai xương rồng (biến dạng của lá) và gai hoa hồng (biến dạng của biểu bì thân) là ví dụ về loại bằng chứng tiến hóa nào?","opts":["Cơ quan tương tự (phản ánh tiến hóa đồng quy).","Cơ quan thoái hóa.","Cơ quan tương đồng (phản ánh tiến hóa phân ly).","Bằng chứng phôi sinh học."],"ans":0,"exp":"Các cơ quan có nguồn gốc cấu tạo khác nhau nhưng thực hiện chức năng giống nhau do sống trong môi trường tương tự là cơ quan tương tự (tiến hóa đồng quy)."},{"id":"MCQ-PO-006","topic":"population","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Phả hệ cơ bản","q":"Khi phân tích một sơ đồ phả hệ, người ta thấy có một cặp bố mẹ đều KHÔNG mắc bệnh nhưng sinh ra một người con GÁI mắc bệnh. Quy luật di truyền của bệnh này chắc chắn là:","opts":["Do gen trội trên NST thường quy định.","Do gen lặn nằm trên nhiễm sắc thể thường quy định.","Do gen trên NST Y quy định.","Do gen lặn nằm trên vùng không tương đồng của NST X quy định."],"ans":1,"exp":"Bố mẹ bình thường sinh con bệnh $\\rightarrow$ Bệnh do gen lặn. Vì con gái bị bệnh mà bố bình thường nên gen chắc chắn nằm trên NST thường."},{"id":"MCQ-PO-007","topic":"population","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Cách ly Sinh sản","q":"Ngựa cái giao phối với lừa đực sinh ra con la khỏe mạnh nhưng con la lại bị bất thụ (không có khả năng sinh con). Đây là ví dụ về dạng cách ly sinh sản nào?","opts":["Cách ly cơ học.","Cách ly sau hợp tử (con lai bất thụ).","Cách ly trước hợp tử (cách ly tập tính).","Cách ly nơi ở (sinh cảnh)."],"ans":1,"exp":"Đã thụ tinh tạo được hợp tử và phát triển thành con la, nhưng con la bất thụ $\\Rightarrow$ Cách ly sau hợp tử."},{"id":"MCQ-PO-008","topic":"population","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Chọn lọc trong Quần thể","q":"Một quần thể thực vật giao phấn ngẫu nhiên có cấu trúc ban đầu $P: 0.5 AA : 0.5 Aa$. Biết hợp tử $aa$ chết ở giai đoạn phôi. Tỉ lệ cá thể mang kiểu gen dị hợp $Aa$ ở thế hệ $F_2$ (khi trưởng thành) là:","opts":["$\\frac{2}{7}$.","$\\frac{1}{3}$.","$\\frac{2}{5}$.","$\\frac{4}{9}$."],"ans":1,"exp":"$q_0 = 1/4 \\rightarrow$ Giao tử của $F_1$ có $q_1 = \\frac{1/4}{1 + 1/4} = \\frac{1}{5}; p_1 = \\frac{4}{5}$. Hợp tử $F_2$: $\\frac{16}{25}AA : \\frac{8}{25}Aa : \\frac{1}{25}aa$ (chết) $\\Rightarrow Aa$ trưởng thành $= \\frac{8}{24} = \\frac{1}{3}$."},{"id":"MCQ-PO-009","topic":"population","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Phả hệ + Quần thể","q":"Bệnh PKU do alen lặn $a$ trên NST thường quy định. Trong một quần thể cân bằng có $1\\%$ người mắc bệnh. Một phụ nữ bình thường (có anh trai bị bệnh, bố mẹ bình thường) kết hôn với một người đàn ông bình thường thuộc quần thể này. Xác suất họ sinh con đầu lòng bị bệnh là:","opts":["$\\frac{1}{33}$.","$\\frac{1}{22}$.","$\\frac{1}{66}$.","$\\frac{1}{44}$."],"ans":0,"exp":"Vợ cho giao tử $a = \\frac{1}{3}$; Chồng thuộc quần thể ($q = 0.1$) cho giao tử $a = \\frac{q}{1+q} = \\frac{1}{11} \\Rightarrow aa = \\frac{1}{33}$."},{"id":"MCQ-PO-010","topic":"population","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Quần thể Đa alen","q":"Ở một loài động vật, tính trạng màu lông do 1 gen có 3 alen trên NST thường quy định: $A_1$ (đen) $> A_2$ (xám) $> A_3$ (trắng). Trong một quần thể cân bằng có $4\\%$ cá thể lông trắng và $32\\%$ cá thể lông xám. Tỉ lệ cá thể lông đen thuần chủng ($A_1 A_1$) trong quần thể là:","opts":["$64\\%$.","$36\\%$.","$16\\%$.","$25\\%$."],"ans":2,"exp":"$r(A_3) = \\sqrt{0.04} = 0.2$; $(q+r)^2 = 0.36 \\Rightarrow q(A_2) = 0.4 \\Rightarrow p(A_1) = 0.4 \\Rightarrow A_1 A_1 = p^2 = 16\\%$."},{"id":"MCQ-PO-011","topic":"population","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Quần thể Gen trên NST X","q":"Ở người, bệnh mù màu do gen lặn $m$ trên vùng không tương đồng của NST X quy định. Trong một quần thể cân bằng, tỉ lệ nam giới bị mù màu là $8\\%$. Tỉ lệ nữ giới trong số các nữ giới của quần thể có thị giác bình thường nhưng mang alen gây bệnh ($X^M X^m$) là:","opts":["$7.36\\%$.","$16\\%$.","$14.72\\%$.","$0.64\\%$."],"ans":2,"exp":"$q(X^m) = 0.08 \\Rightarrow p(X^M) = 0.92 \\Rightarrow$ Ở nữ giới, $X^M X^m = 2pq = 2 \\times 0.92 \\times 0.08 = 14.72\\%$."},{"id":"MCQ-PO-012","topic":"population","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Giao phối có chọn lọc","q":"Quần thể $P$ có cấu trúc $0.4 AA : 0.4 Aa : 0.2 aa$. Nếu các cá thể chỉ giao phấn ngẫu nhiên trong phạm vi những cá thể có CÙNG KIỂU HÌNH (Trội $\\times$ Trội, Lặn $\\times$ Lặn) thì tỉ lệ kiểu gen đồng hợp lặn ($aa$) ở thế hệ $F_1$ là:","opts":["$0.30$.","$0.25$.","$0.22$.","$0.2025$."],"ans":1,"exp":"Nhóm lặn ($0.2 aa$) tạo $0.2 aa$. Nhóm trội ($0.8$, gồm $\\frac{1}{2}AA : \\frac{1}{2}Aa$, cho giao tử $a = \\frac{1}{4}$) tạo $0.8 \\times (\\frac{1}{4})^2 = 0.05 aa \\Rightarrow$ Tổng $aa = 0.25$."},{"id":"MCQ-PO-013","topic":"population","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Phả hệ Sinh 2 con","q":"Một cặp vợ chồng đều có kiểu gen dị hợp $Aa$ về bệnh bạch tạng. Họ dự định sinh 2 người con. Xác suất để trong 2 người con sinh ra có ĐÚNG 1 người con trai bình thường và 1 người con gái bị bệnh là:","opts":["$\\frac{3}{16}$.","$\\frac{9}{64}$.","$\\frac{3}{32}$.","$\\frac{3}{64}$."],"ans":2,"exp":"XS $= C^1_2 \\times (\\frac{1}{2} \\times \\frac{3}{4}) \\times (\\frac{1}{2} \\times \\frac{1}{4}) = 2 \\times \\frac{3}{8} \\times \\frac{1}{8} = \\frac{3}{32}$."},{"id":"MCQ-PO-014","topic":"population","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Các hình thức Chọn lọc Tự nhiên","q":"Ở trẻ sơ sinh người, những trẻ có cân nặng trung bình (khoảng $3.0 - 3.5\\text{ kg}$) có tỉ lệ sống sót cao nhất, trong khi trẻ quá nhẹ cân hoặc quá nặng cân đều có tỉ lệ tử vong cao hơn. Đây là ví dụ điển hình của hình thức chọn lọc tự nhiên nào?","opts":["Chọn lọc phân hóa / gián đoạn (Disruptive selection).","Chọn lọc ổn định / kiên định (Stabilizing selection).","Chọn lọc phụ thuộc tần số.","Chọn lọc định hướng (Directional selection)."],"ans":1,"exp":"Chọn lọc giữ lại các cá thể mang tính trạng trung bình và đào thải các cá thể ở hai đầu cực đoan của phổ biến dị là Chọn lọc ổn định (Stabilizing selection)."},{"id":"MCQ-PO-015","topic":"population","level":"hsg","levelText":"🔴 HSG Tỉnh","subtopic":"Ưu thế dị hợp - Đề HSG Tỉnh","q":"Trong một quần thể có hiện tượng ưu thế dị hợp tử, hệ số chọn lọc chống lại kiểu gen $AA$ là $s_1 = 0.15$ và chống lại kiểu gen $aa$ là $s_2 = 0.45$ ($w_{Aa} = 1$). Tần số alen lặn $q(a)$ khi quần thể đạt cân bằng là:","opts":["$0.33$.","$0.75$.","$0.15$.","$0.25$."],"ans":3,"exp":"$\\hat{q} = \\frac{s_1}{s_1 + s_2} = \\frac{0.15}{0.15 + 0.45} = 0.25$."},{"id":"MCQ-PO-016","topic":"population","level":"hsg","levelText":"🔴 HSG Tỉnh","subtopic":"Gen trên NST X không cân bằng 2 giới - Đề HSG Tỉnh","q":"Ở thế hệ $P$, tần số alen $A$ (trên vùng không tương đồng của X) ở giới cái ($XX$) là $p_{\\text{cái (0)}} = 0.9$, ở giới đực ($XY$) là $p_{\\text{đực (0)}} = 0.3$. Khi quần thể đạt cân bằng hoàn toàn sau nhiều thế hệ ngẫu phối thì tần số alen $A$ của quần thể và tần số alen $A$ ở giới đực ngay thế hệ $F_1$ lần lượt là:","opts":["$\\bar{p} = 0.60$ và $p_{\\text{đực (F1)}} = 0.60$.","$\\bar{p} = 0.50$ và $p_{\\text{đực (F1)}} = 0.90$.","$\\bar{p} = 0.70$ và $p_{\\text{đực (F1)}} = 0.90$.","$\\bar{p} = 0.70$ và $p_{\\text{đực (F1)}} = 0.60$."],"ans":2,"exp":"$\\bar{p} = \\frac{2}{3}(0.9) + \\frac{1}{3}(0.3) = 0.70$; Con đực $F_1$ nhận X từ mẹ $P$ nên $p_{\\text{đực (F1)}} = 0.90$."},{"id":"MCQ-PO-017","topic":"population","level":"hsg","levelText":"🔴 HSG Tỉnh","subtopic":"Hệ số nội phối $F$ - Đề HSG Tỉnh","q":"Một quần thể có tần số alen $p(A) = 0.7$ và $q(a) = 0.3$. Do có sự giao phối cận huyết một phần với hệ số nội phối $F = 0.25$, tỉ lệ kiểu gen dị hợp $Aa$ và đồng hợp lặn $aa$ thực tế trong quần thể này lần lượt là:","opts":["$Aa = 0.315$ và $aa = 0.1425$.","$Aa = 0.105$ và $aa = 0.1425$.","$Aa = 0.420$ và $aa = 0.090$.","$Aa = 0.315$ và $aa = 0.090$."],"ans":0,"exp":"$Aa = 2pq(1 - F) = 0.42 \\times 0.75 = 0.315$; $aa = q^2(1 - F) + qF = 0.09 \\times 0.75 + 0.3 \\times 0.25 = 0.1425$."},{"id":"MCQ-PO-018","topic":"population","level":"hsg","levelText":"🔴 HSG Tỉnh","subtopic":"Di nhập gen - Đề HSG Tỉnh","q":"Quần thể đảo A ban đầu có tần số alen $q_0(a) = 0.2$. Mỗi thế hệ có $10\\%$ ($m = 0.1$) cá thể của đảo A là do nhập cư từ đất liền B sang (quần thể đất liền B có tần số $q_m(a) = 0.7$). Tần số alen $a$ của quần thể đảo A sau 1 thế hệ nhập cư là:","opts":["$0.25$.","$0.27$.","$0.45$.","$0.30$."],"ans":0,"exp":"$q_1 = (1 - m)q_0 + m q_m = 0.9 \\times 0.2 + 0.1 \\times 0.7 = 0.25$."},{"id":"MCQ-PO-019","topic":"population","level":"hsg","levelText":"🔴 HSG Tỉnh","subtopic":"Kích thước quần thể hiệu quả $N_e$ - Đề HSG Tỉnh","q":"Trong một khu bảo tồn hươu sao, có 20 con đực trưởng thành và 80 con cái trưởng thành tham gia giao phối. Kích thước quần thể hiệu quả ($N_e$) của đàn hươu này là bao nhiêu?","opts":["$64$ cá thể.","$100$ cá thể.","$50$ cá thể.","$32$ cá thể."],"ans":0,"exp":"$N_e = \\frac{4 N_m N_f}{N_m + N_f} = \\frac{4 \\times 20 \\times 80}{20 + 80} = 64$ cá thể."},{"id":"MCQ-PO-020","topic":"population","level":"hsg","levelText":"🔴 HSG Tỉnh","subtopic":"Cân bằng Đột biến - Chọn lọc - Đề HSG Tỉnh","q":"Một bệnh di truyền lặn trên NST thường có hệ số chọn lọc chống lại kiểu gen $aa$ là $s = 0.5$. Biết tốc độ đột biến thuận từ alen bình thường $A$ thành alen bệnh $a$ là $u = 2 \\times 10^{-6}$ mỗi giao tử trong một thế hệ. Khi quần thể đạt trạng thái cân bằng giữa đột biến và chọn lọc, tần số alen gây bệnh $\\hat{q}(a)$ là:","opts":["$0.002$ ($2 \\times 10^{-3}$).","$4 \\times 10^{-6}$.","$0.0004$.","$0.02$."],"ans":0,"exp":"$\\hat{q} = \\sqrt{\\frac{u}{s}} = \\sqrt{\\frac{2 \\times 10^{-6}}{0.5}} = 2 \\times 10^{-3} = 0.002$."},{"id":"MCQ-PO-021","topic":"population","level":"hsg","levelText":"🔴 HSG Tỉnh","subtopic":"Phả hệ Anh em ruột - Đề HSG Tỉnh","q":"Ở người, bệnh bạch tạng do gen lặn $a$ trên NST thường quy định. Một cặp bố mẹ đều bình thường nhưng đã sinh ra một đứa con bị bệnh bạch tạng. Hai người con tiếp theo của họ (1 trai, 1 gái) đều có kiểu hình bình thường. Nếu giả sử hai anh em ruột bình thường này kết hôn cận huyết với nhau (hoặc tính hệ số cận huyết), xác suất sinh con đầu lòng bị bệnh của họ là bao nhiêu?","opts":["$\\frac{1}{6}$.","$\\frac{1}{16}$.","$\\frac{1}{4}$.","$\\frac{1}{9}$."],"ans":3,"exp":"Bố mẹ là $Aa \\times Aa \\Rightarrow$ Mỗi người con bình thường đều có xác suất kiểu gen là $(\\frac{1}{3}AA : \\frac{2}{3}Aa)$, cho giao tử $a = \\frac{1}{3}$. Do 2 anh em độc lập từ bố mẹ đã biết kiểu gen $Aa \\times Aa$, xác suất cả hai cùng cho giao tử $a$ là $\\frac{1}{3} \\times \\frac{1}{3} = \\frac{1}{9}$."},{"id":"MCQ-PO-022","topic":"population","level":"hsg","levelText":"🔴 HSG Tỉnh","subtopic":"Quần thể Cân bằng 2 Lôcut Liên kết - Đề HSG Tỉnh","q":"Trong một quần thể ngẫu phối, xét 2 lôcut $(A/a)$ và $(B/b)$ cùng nằm trên 1 cặp NST thường. Tần số các alen lần lượt là $p(A) = 0.6, q(a) = 0.4$ và $p(B) = 0.7, q(b) = 0.3$. Khi quần thể đạt trạng thái cân bằng liên kết hoàn toàn (Linkage equilibrium, $D = 0$), tần số giao tử $\\underline{AB}$ và tỉ lệ kiểu gen dị hợp kép $\\frac{AB}{ab}$ trong quần thể lần lượt là:","opts":["$\\underline{AB} = 0.30$ và $\\frac{AB}{ab} = 0.2400$.","$\\underline{AB} = 0.12$ và $\\frac{AB}{ab} = 0.1008$.","$\\underline{AB} = 0.42$ và $\\frac{AB}{ab} = 0.1008$.","$\\underline{AB} = 0.42$ và $\\frac{AB}{ab} = 0.0504$."],"ans":2,"exp":"Khi cân bằng liên kết hoàn toàn, tần số giao tử bằng tích tần số các alen thành phần: $\\underline{AB} = p(A) \\times p(B) = 0.6 \\times 0.7 = 0.42$; $\\underline{ab} = q(a) \\times q(b) = 0.4 \\times 0.3 = 0.12$. Tỉ lệ kiểu gen $\\frac{AB}{ab} = 2 \\times 0.42 \\times 0.12 = 0.1008$."},{"id":"MCQ-PO-023","topic":"population","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Cấu trúc di truyền Quần thể","q":"Vốn gen của một quần thể sinh vật được hiểu chính xác là gì?","opts":["Tổng số cá thể đực và cái đang sinh sản trong một khu vực phân bố.","Số lượng cặp nhiễm sắc thể lưỡng bội đặc trưng cho loài đó.","Chỉ riêng các alen trội có khả năng biểu hiện ra kiểu hình bên ngoài.","Tập hợp tất cả các alen của tất cả các gen trong quần thể tại một thời điểm xác định."],"ans":3,"exp":"Vốn gen bao gồm toàn bộ các alen của mọi gen hiện diện trong tất cả các cá thể của quần thể tại thời điểm nghiên cứu."},{"id":"MCQ-PO-024","topic":"population","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Cấu trúc di truyền Quần thể","q":"Đặc trưng di truyền cơ bản dùng để phân biệt cấu trúc của hai quần thể cùng loài là:","opts":["Màu sắc lông và kích thước trung bình của các cá thể.","Độ pH trung bình của môi trường đất hoặc nước nơi quần thể sinh sống.","Số lượng chuỗi thức ăn mà quần thể đó tham gia.","Tần số tương đối của các alen và tần số các kiểu gen."],"ans":3,"exp":"Mỗi quần thể có cấu trúc di truyền đặc trưng bởi tần số các alen và tần số các kiểu gen trong vốn gen."},{"id":"MCQ-PO-025","topic":"population","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Quần thể Tự phối","q":"Khi cho một quần thể thực vật có cấu trúc $0.4 AA + 0.6 Aa = 1$ tự thụ phấn bắt buộc liên tiếp qua nhiều thế hệ, xu hướng biến đổi cấu trúc di truyền là:","opts":["Tần số kiểu gen dị hợp giảm dần, tần số các kiểu gen đồng hợp tăng dần, nhưng tần số alen không đổi.","Tần số alen trội $A$ tăng liên tục cho đến khi bằng $1$.","Quần thể nhanh chóng đạt trạng thái cân bằng Hardy-Weinberg ngay ở $F_1$.","Tỉ lệ kiểu gen dị hợp $Aa$ luôn giữ nguyên ở mức $0.6$ qua mọi thế hệ."],"ans":0,"exp":"Tự thụ phấn làm giảm dị hợp tử đi một nửa sau mỗi thế hệ ($H_n = H_0/2^n$) và tăng đồng hợp tử ($AA, aa$), trong khi tần số alen vẫn bảo toàn."},{"id":"MCQ-PO-026","topic":"population","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Quần thể Tự phối","q":"Quá trình giao phối gần (giao phối cận huyết) ở quần thể động vật kéo dài qua nhiều thế hệ thường gây ra hiện tượng thoái hóa giống chủ yếu vì:","opts":["Loại bỏ hoàn toàn các alen trội có lợi ra khỏi nhiễm sắc thể.","Tạo điều kiện cho các alen lặn có hại chuyển từ trạng thái dị hợp sang đồng hợp lặn và biểu hiện ra kiểu hình.","Làm tăng đột ngột tốc độ đột biến gen có hại trong tế bào sinh dưỡng.","Ngăn cản hoàn toàn sự phân ly của nhiễm sắc thể trong giảm phân."],"ans":1,"exp":"Giao phối cận huyết làm tăng tỉ lệ đồng hợp tử lặn, khiến các alen lặn có hại vốn bị che lấp ở thể dị hợp được biểu hiện thành kiểu hình xấu."},{"id":"MCQ-PO-027","topic":"population","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Định luật Hardy-Weinberg","q":"Trong một quần thể ngẫu phối đạt trạng thái cân bằng Hardy-Weinberg với 2 alen $A$ và $a$ trên nhiễm sắc thể thường (tần số lần lượt là $p$ và $q$), tỉ lệ kiểu gen đồng hợp trội $AA$ là:","opts":["$p + q$.","$2pq$.","$q^2$.","$p^2$."],"ans":3,"exp":"Theo phương trình Hardy-Weinberg: $p^2 AA + 2pq Aa + q^2 aa = 1$, trong đó $p^2$ là tần số kiểu gen $AA$."},{"id":"MCQ-PO-028","topic":"population","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Định luật Hardy-Weinberg","q":"Điều kiện nào sau đây KHÔNG phải là điều kiện nghiệm đúng của định luật Hardy-Weinberg?","opts":["Không xảy ra đột biến mới làm thay đổi tần số alen hoặc tỉ lệ đột biến thuận bằng đột biến nghịch.","Kích thước quần thể phải đủ lớn để hạn chế biến động ngẫu nhiên.","Các cá thể trong quần thể phải thực hiện giao phối gần có chọn lọc.","Không có sự di-nhập gen giữa quần thể đang xét và các quần thể lân cận."],"ans":2,"exp":"Định luật Hardy-Weinberg yêu cầu ngẫu phối (giao phối tự do ngẫu nhiên), không chọn lọc tự nhiên, không đột biến, không di-nhập gen và kích thước quần thể lớn."},{"id":"MCQ-PO-029","topic":"population","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Định luật Hardy-Weinberg","q":"Xét một quần thể ngẫu phối đang ở trạng thái cân bằng di truyền với tần số alen lặn $q(a) = 0.3$. Tần số kiểu gen dị hợp $Aa$ trong quần thể này bằng bao nhiêu?","opts":["$0.21$.","$0.09$.","$0.42$.","$0.49$."],"ans":2,"exp":"Ta có $p(A) = 1 - 0.3 = 0.7$. Khi cân bằng, tần số $Aa = 2pq = 2 \\times 0.7 \\times 0.3 = 0.42$."},{"id":"MCQ-PO-030","topic":"population","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Định luật Hardy-Weinberg","q":"Cấu trúc di truyền nào sau đây đang ở trạng thái cân bằng Hardy-Weinberg?","opts":["$0.25 AA + 0.25 Aa + 0.50 aa = 1$.","$0.50 AA + 0.30 Aa + 0.20 aa = 1$.","$0.64 AA + 0.32 Aa + 0.04 aa = 1$.","$0.36 AA + 0.40 Aa + 0.24 aa = 1$."],"ans":2,"exp":"Kiểm tra điều kiện $d \\cdot r = (h/2)^2$: với $0.64 AA + 0.32 Aa + 0.04 aa$, ta có $0.64 \\times 0.04 = 0.0256 = (0.32/2)^2$. Thỏa mãn cân bằng ($p=0.8, q=0.2$)."},{"id":"MCQ-PO-031","topic":"population","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Tính Tần số Alen","q":"Một quần thể khởi đầu có thành phần kiểu gen là $0.25 AA + 0.50 Aa + 0.25 aa = 1$. Tần số alen $A$ và alen $a$ trong quần thể này là:","opts":["$p(A) = 0.25$ và $q(a) = 0.75$.","$p(A) = 0.60$ và $q(a) = 0.40$.","$p(A) = 0.50$ và $q(a) = 0.50$.","$p(A) = 0.75$ và $q(a) = 0.25$."],"ans":2,"exp":"Tần số alen $A$: $p = 0.25 + \\frac{0.50}{2} = 0.50$; tần số alen $a$: $q = 0.25 + \\frac{0.50}{2} = 0.50$."},{"id":"MCQ-PO-032","topic":"population","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Quần thể Tự phối","q":"Cho một quần thể có cấu trúc $100\\% Aa$ tự thụ phấn bắt buộc qua $3$ thế hệ liên tiếp. Tỉ lệ kiểu gen dị hợp $Aa$ thu được ở thế hệ $F_3$ là:","opts":["$12.5\\%$ ($\\frac{1}{8}$).","$50.0\\%$ ($\\frac{1}{2}$).","$25.0\\%$ ($\\frac{1}{4}$).","$6.25\\%$ ($\\frac{1}{16}$)."],"ans":0,"exp":"Áp dụng công thức tự thụ phấn: sau $n = 3$ thế hệ, tỉ lệ $Aa$ ở $F_3 = 1.0 \\times (\\frac{1}{2})^3 = \\frac{1}{8} = 12.5\\%$."},{"id":"MCQ-PO-033","topic":"population","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Đặc trưng Quần thể Sinh thái","q":"Kiểu phân bố phổ biến nhất của các cá thể trong quần thể sinh vật ngoài tự nhiên, giúp các cá thể hỗ trợ nhau chống lại điều kiện bất lợi, là:","opts":["Phân bố theo nhóm.","Phân bố đồng đều.","Phân bố bậc thang đơn độc.","Phân bố ngẫu nhiên tuyệt đối."],"ans":0,"exp":"Phân bố theo nhóm là phổ biến nhất vì điều kiện sống thường không đồng đều và các cá thể tập trung hỗ trợ nhau kiếm ăn, tự vệ."},{"id":"MCQ-PO-034","topic":"population","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Đặc trưng Quần thể Sinh thái","q":"Kiểu phân bố đồng đều của các cá thể trong quần thể (ví dụ chim hải âu làm tổ trên đảo) có ý nghĩa sinh thái nổi bật là:","opts":["Thúc đẩy sự kết đàn săn mồi của các loài thú ăn thịt.","Tăng hiệu quả thụ phấn chéo nhờ gió trong rừng rậm nhiệt đới.","Làm giảm mức độ cạnh tranh gay gắt giữa các cá thể cùng loài về không gian sống và nguồn thức ăn.","Tận dụng nguồn sống tiềm tàng khi môi trường hoàn toàn đồng nhất và không có sự cạnh tranh."],"ans":2,"exp":"Phân bố đồng đều thường gặp khi điều kiện sống phân bố đồng đều và có sự cạnh tranh gay gắt giữa các cá thể, giúp giảm đụng độ và khai thác hiệu quả lãnh thổ."},{"id":"MCQ-PO-035","topic":"population","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Đặc trưng Quần thể Sinh thái","q":"Tỉ lệ giới tính đặc trưng của hầu hết các loài sinh sản hữu tính ở giai đoạn trưởng thành thường xấp xỉ $1:1$ vì nguyên nhân chủ yếu nào?","opts":["Cơ chế giảm phân tạo giao tử mang NST X và Y (hoặc Z và W) với xác suất ngang nhau $1:1$ ở giới dị giao tử.","Tất cả các loài động vật đều có tuổi thọ con đực cao gấp đôi con cái.","Con đực và con cái đều chỉ sống đơn độc ngoài mùa sinh sản.","Nhiệt độ môi trường luôn cố định ở mức tối ưu cho cả 2 giới."],"ans":0,"exp":"Sự phân ly cặp NST giới tính dị giao ($XY \\rightarrow 50\\% X : 50\\% Y$) kết hợp thụ tinh ngẫu nhiên tạo hợp tử $XX : XY \\approx 1:1$."},{"id":"MCQ-PO-036","topic":"population","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Đặc trưng Quần thể Sinh thái","q":"Dựa vào tháp tuổi của quần thể, trạng thái tháp có đáy rất rộng, số lượng cá thể ở nhóm tuổi trước sinh sản lớn vượt trội so với nhóm sinh sản và sau sinh sản biểu thị:","opts":["Quần thể đang phát triển (kích thước có xu hướng tăng nhanh).","Quần thể đã đạt trạng thái già cỗi hoàn toàn.","Quần thể đang suy thoái có nguy cơ diệt vong.","Quần thể đang ổn định về số lượng."],"ans":0,"exp":"Tháp tuổi đáy rộng biểu hiện tỷ lệ sinh cao, nguồn cá thể chuẩn bị bước vào độ tuổi sinh sản lớn, chứng tỏ quần thể đang phát triển."},{"id":"MCQ-PO-037","topic":"population","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Nhân tố Tiến hóa","q":"Theo thuyết tiến hóa tổng hợp hiện đại, nguồn nguyên liệu SƠ CẤP chủ yếu của quá trình tiến hóa là:","opts":["Thường biến thích nghi của cơ thể trước môi trường.","Biến dị đột biến (đặc biệt là đột biến gen).","Các biến dị tổ hợp tạo ra trong quá trình giao phối.","Các cá thể nhập cư từ quần thể lân cận khác loài."],"ans":1,"exp":"Đột biến tạo ra các alen mới nên là nguồn nguyên liệu sơ cấp; quá trình giao phối trộn lẫn các alen tạo biến dị tổ hợp là nguồn nguyên liệu thứ cấp."},{"id":"MCQ-PO-038","topic":"population","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Nhân tố Tiến hóa","q":"Nhân tố tiến hóa nào đóng vai trò quy định CHIỀU HƯỚNG và nhịp điệu của quá trình tiến hóa thích nghi?","opts":["Các yếu tố ngẫu nhiên (phiêu bạt di truyền).","Đột biến.","Chọn lọc tự nhiên.","Giao phối không ngẫu nhiên."],"ans":2,"exp":"Chọn lọc tự nhiên giữ lại các cá thể mang kiểu gen quy định kiểu hình thích nghi và đào thải kiểu hình kém thích nghi, do đó quy định chiều hướng tiến hóa."},{"id":"MCQ-PO-039","topic":"population","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Nhân tố Tiến hóa","q":"Trong thuyết tiến hóa hiện đại, nhân tố nào vừa làm thay đổi tần số alen của quần thể theo một hướng KHÔNG XÁC ĐỊNH, vừa có thể làm nghèo vốn gen và thậm chí loại bỏ hoàn toàn một alen có lợi?","opts":["Cách ly địa lý.","Chọn lọc tự nhiên.","Các yếu tố ngẫu nhiên (biến động di truyền / phiêu bạt di truyền).","Giao phối không ngẫu nhiên."],"ans":2,"exp":"Các yếu tố ngẫu nhiên (thiên tai, hiệu ứng cổ chai, hiệu ứng kẻ sáng lập) tác động vô hướng, đặc biệt mạnh ở quần thể kích thước nhỏ, dễ làm mất alen bất kể lợi hay hại."},{"id":"MCQ-PO-040","topic":"population","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Nhân tố Tiến hóa","q":"Nhân tố tiến hóa nào KHÔNG làm thay đổi tần số các alen của quần thể nhưng lại làm thay đổi thành phần kiểu gen theo hướng tăng dần đồng hợp và giảm dần dị hợp?","opts":["Di - nhập gen.","Đột biến gen.","Giao phối không ngẫu nhiên (tự thụ phấn, giao phối gần, giao phối có lựa chọn).","Chọn lọc tự nhiên."],"ans":2,"exp":"Giao phối không ngẫu nhiên chỉ tái phân phối lại các alen thành tỉ lệ đồng hợp cao hơn và dị hợp thấp hơn chứ không thêm hay bớt alen khỏi vốn gen."},{"id":"MCQ-PO-041","topic":"population","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Nhân tố Tiến hóa","q":"Mức độ tác động làm thay đổi tần số alen của đột biến gen đối với một gen riêng lẻ trong một thế hệ thường rất chậm vì:","opts":["Đột biến gen luôn gây chết hợp tử ngay lập tức.","Mọi đột biến gen đều là đột biến trung tính không di truyền được.","Tế bào sinh dục không bao giờ xảy ra đột biến.","Tần số phát sinh đột biến tự nhiên ở từng gen rất thấp ($10^{-6}$ đến $10^{-4}$)."],"ans":3,"exp":"Dù tần số đột biến trên từng gen thấp ($10^{-6}-10^{-4}$) nên áp lực biến đổi tần số alen qua 1 thế hệ yếu, nhưng do số lượng gen trong hệ gen lớn nên nguồn alen mới vẫn rất dồi dào."},{"id":"MCQ-PO-042","topic":"population","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Nhân tố Tiến hóa","q":"Di - nhập gen (dòng gen) có thể mang đến cho quần thể nhận tác động di truyền nào sau đây?","opts":["Luôn luôn làm giảm sự đa dạng di truyền của mọi quần thể nhận.","Có thể mang thêm các alen mới làm phong phú vốn gen hoặc làm thay đổi tần số alen sẵn có của quần thể nhận.","Chỉ làm thay đổi thành phần kiểu gen mà tuyệt đối không làm đổi tần số alen.","Chỉ xảy ra khi quần thể có kích thước dưới $10$ cá thể."],"ans":1,"exp":"Di cư và nhập cư đưa vào (hoặc mang đi) các alen và kiểu gen, do đó có thể bổ sung alen mới và làm thay đổi tần số alen của quần thể."},{"id":"MCQ-PO-043","topic":"population","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Bằng chứng Tiến hóa","q":"Cơ quan tương đồng (ví dụ: chi trước của mèo, cánh dơi, tay người, vây ngực cá voi) là những cơ quan có đặc điểm nào?","opts":["Có cùng nguồn gốc phôi sinh ở tổ tiên chung nhưng hiện tại thực hiện các chức năng khác nhau.","Có nguồn gốc hoàn toàn khác nhau nhưng phát triển hình thái giống nhau do sống trong môi trường tương tự.","Không còn cấu tạo xương mà đã biến mất hoàn toàn trong quá trình phát triển phôi.","Chỉ tồn tại ở thực vật hạt trần và nấm đa bào."],"ans":0,"exp":"Cơ quan tương đồng bắt nguồn từ cùng một cơ quan ở loài tổ tiên, tiến hóa phân ly thích nghi với môi trường sống và chức năng khác nhau."},{"id":"MCQ-PO-044","topic":"population","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Bằng chứng Tiến hóa","q":"Mắt của mực ống (thân mềm) và mắt của động vật có xương sống đều có cấu tạo dạng thấu kính hội tụ phức tạp với võng mạc cảm quang, nhưng phát triển từ các lớp mô phôi khác nhau (lộn ngược vs không lộn ngược). Đây là ví dụ điển hình về:","opts":["Cơ quan tương tự (phản ánh tiến hóa đồng quy thích nghi).","Cơ quan tương đồng (phản ánh tiến hóa phân ly).","Bằng chứng phôi sinh học cộng sinh.","Cơ quan thoái hóa."],"ans":0,"exp":"Mắt kiểu camera ở mực ống và ở động vật có xương sống tiến hóa độc lập từ các tổ tiên không có cấu trúc mắt tương đồng $\\rightarrow$ cơ quan tương tự do tiến hóa đồng quy."},{"id":"MCQ-PO-045","topic":"population","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Bằng chứng Tiến hóa","q":"Trong cơ thể người, ruột thừa, răng khôn và xương cụt được xếp vào nhóm bằng chứng tiến hóa nào?","opts":["Cơ quan tương tự.","Hóa thạch chuyển tiếp.","Cơ quan thoái hóa (một dạng đặc biệt của cơ quan tương đồng).","Bằng chứng sinh học phân tử."],"ans":2,"exp":"Cơ quan thoái hóa là cơ quan phát triển không đầy đủ ở cơ thể trưởng thành do mất chức năng ở tổ tiên, chứng tỏ nguồn gốc từ các loài tổ tiên có cơ quan đó phát triển đầy đủ."},{"id":"MCQ-PO-046","topic":"population","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Bằng chứng Tiến hóa","q":"Trong các bằng chứng tiến hóa trực tiếp và gián tiếp, bằng chứng nào được xem là bằng chứng TRỰC TIẾP quan trọng nhất cho thấy lịch sử phát sinh và phát triển của sinh giới qua các đại địa chất?","opts":["Bằng chứng hóa thạch.","Bằng chứng phôi sinh học.","Bằng chứng địa lý sinh vật học.","Bằng chứng giải phẫu so sánh."],"ans":0,"exp":"Hóa thạch là di tích của sinh vật để lại trong các lớp đất đá qua các thời kỳ địa chất, cung cấp bằng chứng trực tiếp về tuổi và lịch sử tiến hóa các loài."},{"id":"MCQ-PO-047","topic":"population","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Bằng chứng Tiến hóa","q":"Bằng chứng sinh học phân tử khẳng định nguồn gốc chung của toàn bộ sinh giới trên Trái Đất dựa trên phát hiện nổi bật nào?","opts":["Tất cả mọi loài đều sinh sản vô tính bằng phân đôi.","Mọi loài sinh vật đều có kích thước hệ gen bằng nhau tuyệt đối.","Cơ quan hô hấp của mọi động vật đều là mang.","Hầu hết các loài sinh vật đều dùng chung một bộ mã di truyền và protein đều được cấu tạo từ $20$ loại axit amin giống nhau."],"ans":3,"exp":"Tính thống nhất về vật chất di truyền ADN/ARN, bảng mã di truyền phổ biến và cấu trúc $20$ axit amin ở mọi loài là bằng chứng phân tử mạnh mẽ cho nguồn gốc chung."},{"id":"MCQ-PO-048","topic":"population","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Học thuyết Tiến hóa","q":"Theo quan niệm của Charles Darwin, đơn vị tác động trực tiếp của chọn lọc tự nhiên là gì?","opts":["Cá thể sinh vật.","Phân tử mARN.","Quần thể giao phối.","Hệ sinh thái."],"ans":0,"exp":"Darwin nhấn mạnh chọn lọc tự nhiên tác động trực tiếp lên từng cá thể (sống sót và sinh sản ưu thế), trong khi thuyết hiện đại bổ sung quần thể là đơn vị tiến hóa cơ sở."},{"id":"MCQ-PO-049","topic":"population","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Học thuyết Tiến hóa","q":"Theo thuyết tiến hóa tổng hợp hiện đại, đơn vị tiến hóa cơ sở là gì?","opts":["Tế bào sinh dưỡng.","Quần xã sinh vật.","Quần thể.","Cá thể đơn lẻ."],"ans":2,"exp":"Quần thể là đơn vị tiến hóa cơ sở vì quần thể tồn tại lâu dài qua các thế hệ với vốn gen đặc trưng có thể biến đổi cấu trúc di truyền."},{"id":"MCQ-PO-050","topic":"population","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Học thuyết Tiến hóa","q":"Tiến hóa nhỏ được định nghĩa trong sinh học tiến hóa hiện đại là quá trình:","opts":["Biến đổi cấu trúc di truyền (tần số alen và thành phần kiểu gen) của quần thể dẫn đến hình thành loài mới.","Chỉ xảy ra đột biến thay thế một cặp nucleotit ở tế bào soma.","Hình thành các đơn vị phân loại trên loài như chi, họ, bộ, lớp, ngành.","Chuyển hóa các chất vô cơ thành đại phân tử hữu cơ trong đại dương nguyên thủy."],"ans":0,"exp":"Tiến hóa nhỏ diễn ra trong phạm vi quần thể, kết thúc khi xuất hiện cách ly sinh sản hình thành nên loài mới."},{"id":"MCQ-PO-051","topic":"population","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Học thuyết Tiến hóa","q":"Theo quan điểm hiện đại, quá trình chọn lọc tự nhiên tác động trực tiếp lên cấp độ nào để gián tiếp làm biến đổi vốn gen quần thể?","opts":["Chỉ tác động lên giao tử đơn bội trước khi thụ tinh.","Tác động trực tiếp lên kiểu hình của các cá thể.","Tác động trực tiếp lên từng nucleotit trong nhân tế bào.","Tác động trực tiếp vào lưới nội chất hạt."],"ans":1,"exp":"Môi trường sàng lọc trực tiếp thông qua kiểu hình biểu hiện của cá thể; cá thể có kiểu hình thích nghi sẽ sống sót và truyền alen cho đời sau."},{"id":"MCQ-PO-052","topic":"population","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Hình thành Loài","q":"Tiêu chuẩn quan trọng nhất để phân biệt hai loài sinh vật có quan hệ họ hàng gần gũi sinh sản hữu tính sống chung một khu vực phân bố là:","opts":["Tiêu chuẩn màu sắc hoa hay bộ lông.","Tiêu chuẩn hình thái bề ngoài.","Tiêu chuẩn kích thước lá hoặc cân nặng.","Tiêu chuẩn cách ly sinh sản (tiêu chuẩn di truyền)."],"ans":3,"exp":"Hai loài khác nhau dù có hình thái tương đồng vẫn không giao phối tự nhiên được hoặc tạo con lai bất thụ do có cơ chế cách ly sinh sản."},{"id":"MCQ-PO-053","topic":"population","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Hình thành Loài","q":"Trong tự nhiên, cơ chế cách ly trước hợp tử có bản chất là:","opts":["Sự bất thụ của con lai $F_1$ (như con la tạo từ lừa và ngựa).","Sự thoái hóa của đời lai $F_2$ do xung đột gen.","Những trở ngại làm hợp tử bị chết non ở giai đoạn phôi.","Những trở ngại ngăn cản các sinh vật giao phối với nhau hoặc ngăn cản sự thụ tinh tạo hợp tử."],"ans":3,"exp":"Cách ly trước hợp tử gồm cách ly nơi ở, cách ly tập tính, cách ly thời gian (mùa vụ) và cách ly cơ học — ngăn tạo thành hợp tử."},{"id":"MCQ-PO-054","topic":"population","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Hình thành Loài","q":"Khi lai giữa hai loài thực vật chi *Gossypium* (bông), con lai $F_1$ vẫn sống khỏe và sinh sản được, nhưng đời $F_2$ thu được lại yếu ớt, còi cọc và chết non hàng loạt do mất cân bằng tổ hợp gen (suy thoái đời lai $F_2$). Hiện tượng này thuộc cơ chế nào?","opts":["Cách ly sau hợp tử (suy giảm sức sống / bất thụ ở đời con lai $F_2$).","Cách ly thời gian sinh sản.","Cách ly tập tính giao phối.","Cách ly cơ học giữa cơ quan sinh sản."],"ans":0,"exp":"Dù đã tạo được hợp tử $F_1$ hữu thụ, nhưng sự tái tổ hợp hệ gen ở $F_2$ phá vỡ các nhóm gen đồng thích nghi $\\rightarrow$ suy thoái đời lai (hybrid breakdown), thuộc cách ly sau hợp tử."},{"id":"MCQ-PO-055","topic":"population","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Hình thành Loài","q":"Con đường hình thành loài phổ biến xảy ra nhanh chóng ngay trong cùng một khu vực địa lý ở thực vật có hoa nhờ kết hợp lai xa và gây đột biến số lượng NST là:","opts":["Lai xa và đa bội hóa (tạo thể song nhị bội hữu thụ).","Cách ly địa lý qua hàng triệu năm tách lục địa.","Giao phối cận huyết liên tiếp giữa các cá thể cùng kiểu gen lặn.","Chọn lọc nhân tạo chọn các cây không có hạt."],"ans":0,"exp":"Lai xa tạo con lai $F_1$ bất thụ, sau đó đa bội hóa bộ NST tạo thể song nhị bội ($2n_A + 2n_B$) giảm phân bình thường $\\rightarrow$ loài mới cách ly sinh sản ngay lập tức."},{"id":"MCQ-PO-056","topic":"population","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Hình thành Loài","q":"Trong cơ chế hình thành loài bằng con đường cách ly địa lý, vai trò chính của các chướng ngại địa lý (núi cao, biển rộng, sa mạc) là gì?","opts":["Ngăn cản sự giao lưu vốn gen (cách ly dòng gen) giữa các quần thể, giúp chúng tích lũy biến dị theo các hướng khác nhau.","Trực tiếp gây ra hàng loạt đột biến đa bội cho các cá thể di cư.","Thay thế hoàn toàn vai trò của chọn lọc tự nhiên.","Làm các quần thể tách rời luôn luôn biến thành cùng một loài duy nhất."],"ans":0,"exp":"Chướng ngại địa lý không trực tiếp tạo đột biến hay ép cách ly sinh sản ngay, mà ngăn cản di-nhập gen để chọn lọc tự nhiên và phiêu bạt làm phân hóa vốn gen."},{"id":"MCQ-PO-057","topic":"population","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Phát sinh Sự sống","q":"Thí nghiệm kinh điển năm 1953 của Stanley Miller và Harold Urey chứng minh giai đoạn nào trong lịch sử phát sinh sự sống trên Trái Đất?","opts":["Phân tử ADN mạch kép xuất hiện trước ARN rất lâu.","Các chất hữu cơ đơn giản (như axit amin) có thể hình thành bằng con đường hóa học từ các chất vô cơ dưới điều kiện khí quyển nguyên thủy và phóng điện.","Thực vật hạt kín xuất hiện ngay từ đại Thái cổ.","Tế bào nhân thực cổ đại xuất hiện nhờ cộng sinh ty thể hiếu khí."],"ans":1,"exp":"Miller-Urey mô phỏng khí quyển khử nguyên thủy ($CH_4, NH_3, H_2$, hơi nước) + tia lửa điện đã tổng hợp được nhiều axit amin, chứng minh tiến hóa hóa học."},{"id":"MCQ-PO-058","topic":"population","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Phát sinh Sự sống","q":"Trong tiến hóa tiền sinh học, giả thuyết 'Thế giới ARN' cho rằng đại phân tử sinh học đầu tiên đóng vai trò vừa mang thông tin di truyền vừa có khả năng tự xúc tác (ribozyme) là:","opts":["ARN.","ADN.","Lipid kép.","Polysaccharide."],"ans":0,"exp":"ARN có khả năng lưu giữ trình tự di truyền vừa có hoạt tính xúc tác (ribozyme) nên được xem là hệ thống tự nhân đôi xuất hiện trước ADN và protein."},{"id":"MCQ-PO-059","topic":"population","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Phát sinh Sự sống","q":"Theo trình tự lịch sử phát triển sinh giới qua các đại địa chất, loài người hiện đại (*Homo sapiens*) xuất hiện trong kỷ nào của đại Tân sinh?","opts":["Kỷ Silur của đại Cổ sinh.","Kỷ Cambri.","Kỷ Đệ tứ (Tứ kỷ).","Kỷ Tam điệp (Trias)."],"ans":2,"exp":"Đại Tân sinh gồm kỷ Đệ tam (phát triển chim, thú, thực vật có hoa) và kỷ Đệ tứ (xuất hiện loài người)."},{"id":"MCQ-PO-060","topic":"population","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Phát sinh Sự sống","q":"Sinh vật nhân thực đa bào có lẽ đã tiến hóa mạnh vào khoảng cuối kỷ nguyên nào và sự chuyển lên cạn của thực vật, động vật đầu tiên gắn liền với tầng khí quyển nào được hình thành?","opts":["Sự đóng băng hoàn toàn tất cả các đại dương trên toàn cầu.","Tầng ozon ($O_3$) bảo vệ sinh vật khỏi tia cực tím (UV) gây hại.","Sự biến mất hoàn toàn của khí nitơ ($N_2$).","Sự tăng đột biến nồng độ khí metan ($CH_4$) trên đất liền."],"ans":1,"exp":"Quang hợp của vi khuẩn lam tích lũy $O_2$ tạo nên tầng ozon ($O_3$) hấp thụ tia UV, mở đường cho sinh vật di cư từ đại dương lên đất liền (kỷ Silur)."},{"id":"MCQ-PO-061","topic":"population","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Nhân tố Tiến hóa","q":"Khi môi trường sống đột ngột xảy ra hỏa hoạn làm chết ngẫu nhiên $95\\%$ cá thể của một quần thể thực vật bản địa, hiện tượng làm biến đổi mạnh vốn gen của $5\\%$ cá thể sống sót được gọi là:","opts":["Hiệu ứng thắt cổ chai (hiệu ứng cổ chai di truyền).","Chọn lọc ổn định hoàn hảo.","Cách ly tập tính giao phối.","Hiện tượng cộng sinh hai chiều."],"ans":0,"exp":"Thảm họa tự nhiên thu hẹp kích thước quần thể đột ngột khiến vốn gen sống sót mang tính ngẫu nhiên không phản ánh quần thể gốc — gọi là hiệu ứng thắt cổ chai."},{"id":"MCQ-PO-062","topic":"population","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Quần thể & Hardy-Weinberg","q":"Một quần thể động vật ngẫu phối có tần số alen $A = 0.6$ và $a = 0.4$. Khi đạt cân bằng di truyền, tổng tỉ lệ các cá thể có kiểu hình trội ($A-$) trong quần thể là bao nhiêu?","opts":["$84\\%$.","$36\\%$.","$64\\%$.","$48\\%$."],"ans":0,"exp":"Tần số kiểu hình lặn $aa = q^2 = 0.4^2 = 0.16 = 16\\% \\Rightarrow$ kiểu hình trội $A- = 1 - 0.16 = 0.84 = 84\\%$."},{"id":"MCQ-PO-063","topic":"population","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Quần thể Tự phối","q":"Một quần thể thực vật tự thụ phấn có thành phần kiểu gen ở thế hệ xuất phát $P$ là $0.2 AA + 0.6 Aa + 0.2 aa = 1$. Tần số kiểu gen $AA$ sau $1$ thế hệ tự thụ phấn ($F_1$) là:","opts":["$0.20$.","$0.30$.","$0.35$.","$0.50$."],"ans":2,"exp":"Sau $1$ thế hệ: $Aa = 0.6 \\times 0.5 = 0.30$; $AA = 0.2 + \\frac{0.6 - 0.3}{2} = 0.2 + 0.15 = 0.35$."},{"id":"MCQ-PO-064","topic":"population","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Nhân tố Tiến hóa","q":"Hình thức chọn lọc tự nhiên giữ lại các cá thể mang giá trị tính trạng trung bình và đào thải các cá thể mang giá trị cực đoan về cả hai phía khi điều kiện môi trường ổn định lâu dài gọi là:","opts":["Chọn lọc vận động (chọn lọc định hướng).","Chọn lọc phân hóa.","Chọn lọc ổn định.","Chọn lọc nhân tạo phân ly."],"ans":2,"exp":"Chọn lọc ổn định thu hẹp biên độ biến dị xung quanh giá trị trung bình tối ưu trong môi trường ổn định (ví dụ cân nặng trẻ sơ sinh hay số trứng ở chim)."},{"id":"MCQ-PO-065","topic":"population","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Nhân tố Tiến hóa","q":"Tại vùng công nghiệp ô nhiễm khói than đen ở Anh, tỉ lệ bướm bạch dương (*Biston betularia*) màu đen tăng vọt thay thế bướm màu trắng nhạt. Đây là ví dụ điển hình của hình thức chọn lọc nào?","opts":["Yếu tố ngẫu nhiên hoàn toàn.","Giao phối cận huyết bắt buộc.","Chọn lọc vận động (định hướng).","Chọn lọc ổn định."],"ans":2,"exp":"Môi trường đổi mới theo một chiều (thân cây phủ bụi đen) làm chọn lọc tự nhiên dịch chuyển đặc điểm thích nghi của quần thể về một phía (màu đen) $\\rightarrow$ chọn lọc vận động."},{"id":"MCQ-PO-066","topic":"population","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Quần thể Ngẫu phối","q":"Một quần thể động vật đang ở trạng thái cân bằng Hardy-Weinberg có tần số kiểu hình lặn ($aa$) chiếm $25\\%$. Tần số alen trội $A$ của quần thể là bao nhiêu?","opts":["$0.0625$.","$0.75$.","$0.25$.","$0.50$."],"ans":3,"exp":"Vì cân bằng: $q^2(aa) = 0.25 \\Rightarrow q(a) = \\sqrt{0.25} = 0.50 \\Rightarrow p(A) = 1 - 0.50 = 0.50$."},{"id":"MCQ-PO-067","topic":"population","level":"basic","levelText":"🟢 Cơ bản","subtopic":"Tiến hóa Sinh học","q":"Theo quan điểm tiến hóa hiện đại, quá trình hình thành quần thể thích nghi được xem là kết quả tương tác trực tiếp của các nhân tố nào sau đây?","opts":["Chỉ xảy ra đột biến mất đoạn NST đồng loạt ở $100\\%$ cá thể cùng lúc.","Sự giao phối gần kéo dài làm triệt tiêu mọi alen trội.","Đột biến cung cấp alen mới, giao phối tạo biến dị tổ hợp, và chọn lọc tự nhiên giữ lại kiểu hình thích nghi qua nhiều thế hệ.","Chỉ riêng tác động trực tiếp của thường biến do khí hậu gây ra."],"ans":2,"exp":"Quá trình hình thành đặc điểm thích nghi đòi hỏi nguồn biến dị di truyền (đột biến + giao phối) và sự sàng lọc có hướng của chọn lọc tự nhiên."},{"id":"MCQ-PO-068","topic":"population","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Hardy-Weinberg cơ bản & mở rộng","q":"Ở người, bệnh bạch tạng do gen lặn $a$ trên NST thường quy định. Trong một quần thể đạt trạng thái cân bằng di truyền có tỉ lệ người mắc bệnh bạch tạng là $1/10\\,000$. Tỉ lệ người bình thường mang gen gây bệnh (dị hợp $Aa$) trong quần thể này xấp xỉ là:","opts":["$9.90\\%$.","$0.01\\%$.","$1.98\\%$.","$0.99\\%$."],"ans":2,"exp":"$q^2 = 10^{-4} \\Rightarrow q = 0.01$, $p = 0.99$. Người dị hợp $Aa = 2pq = 2 \\times 0.99 \\times 0.01 = 0.0198 = 1.98\\%$."},{"id":"MCQ-PO-069","topic":"population","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Hardy-Weinberg 3 Alen (Nhóm máu)","q":"Ở người, hệ nhóm máu ABO do $3$ alen $I^A, I^B, I^O$ chi phối ($I^A, I^B$ đồng trội và cùng trội hoàn toàn so với $I^O$). Một quần thể đang cân bằng Hardy-Weinberg có tần số các alen $p(I^A) = 0.3$, $q(I^B) = 0.2$, $r(I^O) = 0.5$. Tỉ lệ người mang nhóm máu A trong quần thể là bao nhiêu?","opts":["$30\\%$.","$25\\%$.","$39\\%$.","$9\\%$."],"ans":2,"exp":"Nhóm máu A gồm $I^A I^A$ ($p^2 = 0.3^2 = 0.09$) và $I^A I^O$ ($2pr = 2 \\times 0.3 \\times 0.5 = 0.30$). Tổng tỉ lệ $= 0.09 + 0.30 = 0.39 = 39\\%$."},{"id":"MCQ-PO-070","topic":"population","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Hardy-Weinberg 3 Alen (Nhóm máu)","q":"Trong một quần thể người cân bằng Hardy-Weinberg về hệ nhóm máu ABO, tỉ lệ người có nhóm máu O là $4\\%$, nhóm máu B là $21\\%$. Tần số các alen $I^A, I^B, I^O$ lần lượt là:","opts":["$I^A = 0.4$, $I^B = 0.4$, $I^O = 0.2$.","$I^A = 0.2$, $I^B = 0.3$, $I^O = 0.5$.","$I^A = 0.5$, $I^B = 0.3$, $I^O = 0.2$.","$I^A = 0.3$, $I^B = 0.5$, $I^O = 0.2$."],"ans":2,"exp":"Nhóm O ($I^O I^O$) $= r^2 = 0.04 \\Rightarrow r = 0.2$. Nhóm B + nhóm O $= (q+r)^2 = 0.21 + 0.04 = 0.25 \\Rightarrow q + r = 0.5 \\Rightarrow q = 0.3$. Suy ra $p(I^A) = 1 - 0.3 - 0.2 = 0.5$."},{"id":"MCQ-PO-071","topic":"population","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Hardy-Weinberg trên X","q":"Ở người, bệnh máu khó đông (Hemophilia A) do alen lặn $h$ nằm trên vùng không tương đồng của NST X quy định. Trong một quần thể người cân bằng Hardy-Weinberg có $4\\%$ số nam giới mắc bệnh máu khó đông. Trong tổng số NỮ GIỚI của quần thể này, tỉ lệ người mang kiểu hình BÌNH THƯỜNG nhưng mang alen gây bệnh ($X^H X^h$) là bao nhiêu?","opts":["$3.84\\%$.","$0.16\\%$.","$7.68\\%$.","$4.00\\%$."],"ans":2,"exp":"Tần số nam bệnh ($X^h Y$) bằng $q(h) = 0.04 \\Rightarrow p(H) = 0.96$. Trong giới nữ ($XX$), tỉ lệ người dị hợp mang gen bệnh $X^H X^h = 2pq = 2 \\times 0.96 \\times 0.04 = 0.0768 = 7.68\\%$."},{"id":"MCQ-PO-072","topic":"population","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Hardy-Weinberg trên X","q":"Tiếp nối trường hợp bệnh mù màu do alen lặn $m$ trên NST X với $q(m) = 0.1$ trong quần thể người cân bằng có tỉ lệ nam:nữ là $1:1$. Tỉ lệ nữ giới bình thường mang alen gây bệnh ($X^M X^m$) tính trong toàn bộ quần thể chung (gồm cả nam và nữ) là bao nhiêu?","opts":["$18\\%$.","$4.5\\%$.","$9\\%$.","$8.1\\%$."],"ans":2,"exp":"Trong giới nữ, tỉ lệ $X^M X^m = 2pq = 2(0.9)(0.1) = 0.18 = 18\\%$. Vì nữ chiếm $50\\%$ toàn quần thể nên tỉ lệ $X^M X^m$ trong toàn quần thể $= 0.5 \\times 18\\% = 9\\%$."},{"id":"MCQ-PO-073","topic":"population","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Quần thể Tự thụ phấn","q":"Một quần thể thực vật ở thế hệ $P$ gồm $0.4 AA + 0.4 Aa + 0.2 aa = 1$. Khi quần thể này tự thụ phấn bắt buộc liên tiếp, cấu trúc di truyền thu được ở thế hệ $F_2$ là:","opts":["$0.50 AA + 0.20 Aa + 0.30 aa = 1$.","$0.40 AA + 0.20 Aa + 0.40 aa = 1$.","$0.60 AA + 0.10 Aa + 0.30 aa = 1$.","$0.55 AA + 0.10 Aa + 0.35 aa = 1$."],"ans":3,"exp":"Sau $n=2$ thế hệ tự thụ: $Aa = 0.4 \\times (1/2)^2 = 0.10$. Lượng giảm dị hợp $0.30$ chia đôi cộng đều vào $AA$ và $aa$: $AA = 0.4 + 0.15 = 0.55$, $aa = 0.2 + 0.15 = 0.35$."},{"id":"MCQ-PO-074","topic":"population","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Quần thể Tự thụ phấn","q":"Một quần thể đậu Hà Lan thế hệ $P$ gồm toàn các cây hoa đỏ có cấu trúc $0.6 AA + 0.4 Aa = 1$ ($A$ hoa đỏ trội hoàn toàn so với $a$ hoa trắng). Nếu cho các cây này tự thụ phấn bắt buộc liên tiếp qua $3$ thế hệ ($F_3$), tỉ lệ cây hoa trắng ở $F_3$ là:","opts":["$15.0\\%$.","$17.5\\%$.","$20.0\\%$.","$5.0\\%$."],"ans":1,"exp":"Ở $F_3$: $Aa = 0.4 \\times (1/2)^3 = 0.05$. Tỉ lệ hoa trắng $aa = 0 + \\frac{0.4 - 0.05}{2} = 0.175 = 17.5\\%$."},{"id":"MCQ-PO-075","topic":"population","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Quần thể Ngẫu phối","q":"Một quần thể động vật ở thế hệ $P$ gồm $0.2 AA + 0.6 Aa + 0.2 aa = 1$. Cho quần thể ngẫu phối tự do qua $1$ thế hệ, cấu trúc di truyền của $F_1$ thu được là:","opts":["$0.25 AA + 0.50 Aa + 0.25 aa = 1$.","$0.35 AA + 0.30 Aa + 0.35 aa = 1$.","$0.16 AA + 0.48 Aa + 0.36 aa = 1$.","$0.36 AA + 0.48 Aa + 0.16 aa = 1$."],"ans":0,"exp":"Từ $P$: $p(A) = 0.2 + 0.3 = 0.5$, $q(a) = 0.5$. Sau $1$ thế hệ ngẫu phối, quần thể đạt ngay cân bằng: $0.5^2 AA + 2(0.5)(0.5) Aa + 0.5^2 aa = 0.25 AA + 0.50 Aa + 0.25 aa$."},{"id":"MCQ-PO-076","topic":"population","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Ngẫu phối từ Hai giới khác nhau","q":"Một quần thể động vật ở thế hệ xuất phát $P$ có tần số alen $A$ ở giới cái là $0.8$ và ở giới đực là $0.4$ (gen trên NST thường). Cho các cá thể ngẫu phối tự do, khi quần thể đạt trạng thái cân bằng di truyền (từ $F_2$) thì tỉ lệ kiểu gen dị hợp $Aa$ là:","opts":["$0.52$.","$0.32$.","$0.48$.","$0.42$."],"ans":2,"exp":"Khi $2$ giới có tần số alen khác nhau (NST thường), sau $F_1$ tần số alen đồng nhất là $p = \\frac{0.8 + 0.4}{2} = 0.6 \\Rightarrow q = 0.4$. Từ $F_2$ cân bằng: $Aa = 2pq = 2(0.6)(0.4) = 0.48$."},{"id":"MCQ-PO-077","topic":"population","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Ngẫu phối từ Hai giới khác nhau","q":"Trong bài toán trên (giới cái $P$ có $p_f = 0.8$, giới đực $P$ có $p_m = 0.4$, gen trên NST thường), cấu trúc di truyền thu được ngay ở thế hệ $F_1$ là bao nhiêu?","opts":["$0.16 AA + 0.48 Aa + 0.36 aa = 1$.","$0.64 AA + 0.32 Aa + 0.04 aa = 1$.","$0.32 AA + 0.56 Aa + 0.12 aa = 1$.","$0.36 AA + 0.48 Aa + 0.16 aa = 1$."],"ans":2,"exp":"Giao tử cái: $0.8 A : 0.2 a$; giao tử đực: $0.4 A : 0.6 a$. Tổ hợp $F_1$: $AA = 0.8 \\times 0.4 = 0.32$, $aa = 0.2 \\times 0.6 = 0.12$, $Aa = 0.8(0.6) + 0.2(0.4) = 0.56$. ($F_1$ chưa cân bằng; phải sang $F_2$ mới cân bằng!)."},{"id":"MCQ-PO-078","topic":"population","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Xác suất Di truyền Quần thể","q":"Ở người, alen $A$ quy định da bình thường trội hoàn toàn so với alen $a$ gây bệnh bạch tạng nằm trên NST thường. Một quần thể người cân bằng di truyền có tỉ lệ người mắc bệnh bạch tạng là $4\\%$. Một cặp vợ chồng đều có da bình thường trong quần thể này kết hôn với nhau. Xác suất để đứa con đầu lòng của họ bị bệnh bạch tạng là:","opts":["$\\frac{1}{16}$.","$\\frac{1}{25}$.","$\\frac{1}{36}$.","$\\frac{1}{9}$."],"ans":2,"exp":"$q^2 = 0.04 \\Rightarrow q = 0.2, p = 0.8$. Trong nhóm người bình thường ($0.64 AA + 0.32 Aa$), tỉ lệ dị hợp $Aa = \\frac{0.32}{0.96} = \\frac{1}{3}$. Xác suất hai người dị hợp kết hôn sinh con $aa = \\frac{1}{3} \\times \\frac{1}{3} \\times \\frac{1}{4} = \\frac{1}{36}$."},{"id":"MCQ-PO-079","topic":"population","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Xác suất Di truyền Quần thể","q":"Trong một quần thể người cân bằng di truyền, gen $a$ gây bệnh phenylketo niệu (trên NST thường) có tần số $q = 0.01$. Một người đàn ông bình thường có chị gái bị bệnh kết hôn với một người phụ nữ bình thường ngẫu nhiên trong quần thể (không biết rõ phả hệ gia đình vợ). Xác suất đứa con đầu lòng mắc bệnh là xấp xỉ:","opts":["$\\frac{1}{200}$.","$\\frac{1}{600}$.","$\\frac{1}{400}$.","$\\frac{1}{303}$."],"ans":3,"exp":"Chị gái bệnh ($aa$) $\\Rightarrow$ bố mẹ chồng $Aa \\times Aa$, nên chồng bình thường có xác suất mang $Aa = \\frac{2}{3}$. Vợ ngẫu nhiên bình thường mang $Aa = \\frac{2q}{1+q} = \\frac{0.02}{1.01} = \\frac{2}{101}$. Con mắc bệnh $aa = \\frac{2}{3} \\times \\frac{2}{101} \\times \\frac{1}{4} = \\frac{1}{303}$."},{"id":"MCQ-PO-080","topic":"population","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Quần thể Chọn lọc","q":"Ở một loài thực vật giao phấn, hạt vàng ($A$) trội hoàn toàn so với hạt xanh ($a$). Thế hệ $P$ có $0.36 AA + 0.48 Aa + 0.16 aa = 1$. Do sâu bệnh chỉ tấn công tiêu diệt toàn bộ các cây mọc từ hạt xanh ($aa$) trước khi ra hoa, các cây còn lại giao phấn ngẫu nhiên sinh ra $F_1$. Tỉ lệ cây hạt xanh thu được ở $F_1$ là bao nhiêu?","opts":["$\\frac{16}{100}$ ($16\\%$).","$\\frac{4}{25}$ ($16\\%$).","$\\frac{4}{49}$ ($\\approx 8.16\\%$).","$\\frac{2}{7}$ ($\\approx 28.57\\%$)."],"ans":2,"exp":"Sau khi loại bỏ $0.16 aa$, quần thể tham gia sinh sản còn $\\frac{0.36}{0.84} AA + \\frac{0.48}{0.84} Aa = \\frac{3}{7} AA + \\frac{4}{7} Aa$. Tần số giao tử $a = \\frac{2}{7}$. Ngẫu phối tạo $aa = (\\frac{2}{7})^2 = \\frac{4}{49}$."},{"id":"MCQ-PO-081","topic":"population","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Quần thể Tự phối kết hợp Chọn lọc","q":"Một quần thể cây tự thụ phấn ở $P$ gồm $0.5 AA + 0.5 Aa = 1$. Biết kiểu gen $aa$ bị chết hoàn toàn ở giai đoạn nảy mầm (không trưởng thành để sinh sản). Thành phần kiểu gen ở giai đoạn cây trưởng thành của thế hệ $F_1$ là:","opts":["$\\frac{3}{4} AA + \\frac{1}{4} Aa$.","$\\frac{5}{7} AA + \\frac{2}{7} Aa$.","$0.625 AA + 0.250 Aa$.","$\\frac{1}{2} AA + \\frac{1}{2} Aa$."],"ans":1,"exp":"Khi tự thụ, hợp tử $F_1$ gồm: $AA = 0.5 + 0.5(0.25) = 0.625$, $Aa = 0.250$, $aa = 0.125$. Vì $aa$ chết, tỷ lệ trưởng thành còn tổng $0.875$: $AA = \\frac{0.625}{0.875} = \\frac{5}{7}$, $Aa = \\frac{0.25}{0.875} = \\frac{2}{7}$."},{"id":"MCQ-PO-082","topic":"population","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Di - nhập gen","q":"Một quần thể $X$ có tần số alen $A$ ban đầu là $0.80$. Do lũ lụt, một đàn cá thể nhập cư từ quần thể $Y$ (có tần số $A = 0.20$) tràn vào làm kích thước đàn nhập cư chiếm $25\\%$ tổng số cá thể sau hợp nhất. Tần số alen $A$ mới của quần thể $X$ ngay sau khi hợp nhất là:","opts":["$0.60$.","$0.65$.","$0.50$.","$0.70$."],"ans":1,"exp":"Áp dụng công thức dòng gen: $p' = (1 - m)p_0 + m p_m = 0.75 \\times 0.80 + 0.25 \\times 0.20 = 0.60 + 0.05 = 0.65$."},{"id":"MCQ-PO-083","topic":"population","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Hardy-Weinberg 2 Locus độc lập","q":"Xét $2$ cặp gen $A/a$ và $B/b$ nằm trên $2$ cặp NST thường khác nhau ở một quần thể ngẫu phối đang cân bằng ở cả $2$ locus với $p(A) = 0.6$, $p(B) = 0.5$ (cân bằng liên kết). Tỉ lệ cá thể mang kiểu gen $AaBb$ trong quần thể là:","opts":["$0.48$.","$0.36$.","$0.24$.","$0.12$."],"ans":2,"exp":"Khi cân bằng độc lập: tỉ lệ $Aa = 2(0.6)(0.4) = 0.48$; tỉ lệ $Bb = 2(0.5)(0.5) = 0.50$. Tỉ lệ $AaBb = 0.48 \\times 0.50 = 0.24$."},{"id":"MCQ-PO-084","topic":"population","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Hardy-Weinberg 2 Locus độc lập","q":"Cùng giả thiết cân bằng ở $2$ gen độc lập ($A$ trội hoàn toàn $a$, $B$ trội hoàn toàn $b$) với $p(A) = 0.7$ và $p(B) = 0.8$. Tỉ lệ cá thể mang kiểu hình trội cả $2$ tính trạng ($A-B-$) trong quần thể là bao nhiêu?","opts":["$96.0\\%$.","$31.36\\%$.","$87.36\\%$.","$91.0\\%$."],"ans":2,"exp":"$A- = 1 - 0.3^2 = 0.91$; $B- = 1 - 0.2^2 = 0.96$. Do 2 locus phân ly độc lập và cân bằng liên kết: $A-B- = 0.91 \\times 0.96 = 0.8736 = 87.36\\%$."},{"id":"MCQ-PO-085","topic":"population","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Giao phối có Chọn lọc theo Kiểu hình","q":"Ở một loài thực vật, các cây hoa đỏ ($0.36 AA + 0.48 Aa$) chỉ thụ phấn ngẫu nhiên trong nhóm hoa đỏ, còn các cây hoa trắng ($0.16 aa$) chỉ thụ phấn với nhau (cách ly sinh thái màu hoa). Tỉ lệ cây hoa trắng ($aa$) thu được ở thế hệ $F_1$ là:","opts":["$\\frac{4}{25}$ ($16.00\\%$).","$\\frac{12}{49}$ ($\\approx 24.49\\%$).","$\\frac{8}{35}$ ($\\approx 22.86\\%$).","$\\frac{1}{4}$ ($25.00\\%$)."],"ans":2,"exp":"Nhóm hoa đỏ chiếm $0.84 = \\frac{21}{25}$ (tỉ lệ nội nhóm $\\frac{3}{7}AA + \\frac{4}{7}Aa$, có $q_a=\\frac{2}{7}$) tự giao phấn tạo $\\frac{4}{49}aa$, đóng góp $\\frac{21}{25} \\times \\frac{4}{49} = \\frac{12}{175}$ vào toàn quần thể. Nhóm hoa trắng ($0.16 = \\frac{28}{175}$) sinh $100\\%$ trắng. Tổng hoa trắng $F_1 = \\frac{12+28}{175} = \\frac{40}{175} = \\frac{8}{35}$."},{"id":"MCQ-PO-086","topic":"population","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Tác động của Giao tử không sống sót","q":"Một quần thể thực vật ở thế hệ $P$ có $0.4 AA + 0.6 Aa = 1$. Biết tất cả các hạt phấn mang alen $a$ đều bị bất thụ (không tham gia thụ tinh), trong khi các noãn mang alen $A$ và $a$ đều hữu thụ bình thường. Khi cho quần thể giao phấn tự do, tỉ lệ kiểu gen $AA$ ở $F_1$ bằng bao nhiêu?","opts":["$0.70$.","$0.64$.","$0.30$.","$0.49$."],"ans":0,"exp":"Hạt phấn chỉ có alen $A$ ($100\\% A$). Noãn tạo ra gồm $p(A) = 0.4 + 0.3 = 0.7 A$ và $q(a) = 0.3 a$. Thụ tinh cho $F_1$: $0.7 AA + 0.3 Aa$. Vậy $AA$ chiếm $0.70$."},{"id":"MCQ-PO-087","topic":"population","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Tác động của Giao tử không sống sót","q":"Tiếp theo dữ kiện trên (P có $0.4 AA + 0.6 Aa$, hạt phấn $a$ bất thụ hoàn toàn), nếu quần thể này TỰ THỤ PHẤN bắt buộc thay vì giao phấn ngẫu nhiên, tỉ lệ kiểu gen dị hợp $Aa$ ở $F_1$ sẽ là bao nhiêu?","opts":["$0.60$.","$0.30$.","$0.15$.","$0.45$."],"ans":1,"exp":"Cây $0.4 AA$ tự thụ phấn tạo $0.4 AA$. Cây $0.6 Aa$ chỉ tạo được hạt phấn $A$ thụ tinh với noãn ($0.5 A : 0.5 a$) tạo $0.3 AA + 0.3 Aa$. Tổng cộng $F_1$ có $0.7 AA + 0.3 Aa$, tức $Aa = 0.30$."},{"id":"MCQ-PO-088","topic":"population","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Kiểm tra Điều kiện Cân bằng","q":"Cho cấu trúc di truyền của 4 quần thể như sau: (I) $0.81 AA + 0.18 Aa + 0.01 aa$; (II) $0.09 AA + 0.42 Aa + 0.49 aa$; (III) $0.49 AA + 0.21 Aa + 0.30 aa$; (IV) $1.00 AA$. Những quần thể nào ĐANG ở trạng thái cân bằng Hardy-Weinberg?","opts":["Quần thể (I), (II) và (IV).","Quần thể (I) và (II).","Quần thể (II) và (III).","Cả 4 quần thể."],"ans":0,"exp":"Kiểm tra $\\sqrt{d} + \\sqrt{r} = 1$: (I) $0.9+0.1=1$ (CB); (II) $0.3+0.7=1$ (CB); (III) $0.7 + \\sqrt{0.3} \\neq 1$ (không CB); (IV) $p=1, q=0 \\Rightarrow 1.0^2 = 1.00 AA$ (CB ở trạng thái cố định alen)."},{"id":"MCQ-PO-089","topic":"population","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Thể đa bội & Cân bằng","q":"Ở một loài thực vật tứ bội ($4n$), xét gen $A$ trội hoàn toàn so với $a$. Một quần thể tứ bội đang cân bằng di truyền (ngẫu phối tạo giao tử $2n$) có tần số alen $p(A) = 0.8$, $q(a) = 0.2$. Tỉ lệ cá thể đồng hợp lặn ($aaaa$) trong quần thể này là:","opts":["$0.04$ ($4\\%$).","$0.0004$.","$0.008$ ($0.8\\%$).","$0.0016$ ($0.16\\%$)."],"ans":3,"exp":"Khi quần thể tứ bội cân bằng ngẫu phối, tần số giao tử lưỡng bội $aa = q^2 = 0.04$. Hợp tử tứ bội đồng hợp lặn $aaaa$ xuất hiện với tần số $(q^2)^2 = q^4 = 0.2^4 = 0.0016$ ($0.16\\%$)."},{"id":"MCQ-PO-090","topic":"population","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Quần thể Động vật & Độ lớn hiệu quả","q":"Xét một quần thể gồm $10$ cá thể đực và $90$ cá thể cái tham gia sinh sản ngẫu nhiên (kích thước thực $N = 100$). Kích thước hiệu quả $N_e$ của quần thể theo công thức $N_e = \\frac{4 N_m N_f}{N_m + N_f}$ là bao nhiêu?","opts":["$50$.","$36$.","$100$.","$18$."],"ans":1,"exp":"Thay $N_m = 10, N_f = 90$: $N_e = \\frac{4 \\times 10 \\times 90}{10 + 90} = \\frac{3600}{100} = 36$. Khi tỉ lệ giới tính lệch mạnh, $N_e$ giảm sâu làm tăng tác động của phiêu bạt di truyền."},{"id":"MCQ-PO-091","topic":"population","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Chọn lọc & Sinh thái tiến hóa","q":"Tại sao trong một quần thể tự nhiên, alen lặn gây bệnh di truyền hiếm gặp rất khó bị chọn lọc tự nhiên đào thải hoàn toàn ra khỏi vốn gen?","opts":["Vì mọi alen lặn đều tự động chuyển thành alen trội khi vào kỳ giảm phân.","Khi $q(a)$ rất nhỏ, phần lớn các alen lặn nằm ẩn trong kiểu gen dị hợp $Aa$ có kiểu hình bình thường nên thoát khỏi sự đào thải của chọn lọc.","Vì giao phối cận huyết làm tăng sức sống cho kiểu gen đồng hợp lặn.","Do đột biến nghịch $A \\rightarrow a$ không bao giờ xảy ra."],"ans":1,"exp":"Với $q$ nhỏ, tỉ lệ $Aa$ ($2pq$) lớn hơn rất nhiều so với $aa$ ($q^2$), ví dụ $q=0.01$ thì $99\\%$ số alen $a$ nằm trong $Aa$ nên được chọn lọc tự nhiên 'bảo hộ' khỏi đào thải."},{"id":"MCQ-PO-092","topic":"population","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Nhân tố Tiến hóa","q":"Phát biểu nào sau đây đúng khi so sánh tác động của nhân tố Đột biến và Di-nhập gen lên vốn gen quần thể?","opts":["Đột biến làm tăng biến dị, còn di-nhập gen luôn luôn làm giảm biến dị của mọi quần thể.","Chỉ có di-nhập gen làm biến đổi tần số alen, đột biến chỉ đổi thành phần kiểu gen.","Cả hai nhân tố đều không phụ thuộc vào môi trường và luôn tác động có hướng cố định.","Cả hai nhân tố đều có khả năng bổ sung alen mới vào vốn gen và làm thay đổi tần số alen, nhưng di-nhập gen thường tạo biến động nhanh hơn trên một locus."],"ans":3,"exp":"Tần số đột biến tự nhiên ở một gen rất nhỏ ($10^{-6}-10^{-4}$), trong khi tốc độ di-nhập gen có thể đạt vài phần trăm mỗi thế hệ nên làm đổi tần số alen nhanh hơn nhiều."},{"id":"MCQ-PO-093","topic":"population","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Tiến hóa Đảo & Hiệu ứng kẻ sáng lập","q":"Một nhóm gồm $12$ cá thể chim sẻ đất liền vô tình bị bão cuốn ra sống tách biệt trên một hòn đảo hoang và hình thành quần thể mới mang nhiều tần số alen khác hẳn quần thể đất liền ban đầu (ví dụ tỉ lệ một alen hiếm lên tới $30\\%$). Đây là biểu hiện rõ nét của:","opts":["Cơ chế hình thành loài bằng đa bội hóa khác nguồn.","Hiệu ứng kẻ sáng lập (một dạng của yếu tố ngẫu nhiên / phiêu bạt di truyền).","Chọn lọc phân hóa có hướng trên đất liền.","Sự thích nghi di truyền trực tiếp dưới tác dụng của gió bão."],"ans":1,"exp":"Một nhóm nhỏ cá thể tách ra lập quần thể mới thường mang mẫu alen lệch ngẫu nhiên so với quần thể gốc $\\rightarrow$ hiệu ứng kẻ sáng lập (founder effect)."},{"id":"MCQ-PO-094","topic":"population","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Cách ly Sinh sản","q":"Hai loài ếch họ hàng sống cùng một ao hồ nhưng một loài kêu gọi bạn tình và đẻ trứng vào đầu mùa xuân, loài kia sinh sản vào cuối mùa hè. Hình thức cách ly sinh sản giữa chúng là:","opts":["Cách ly địa lý tuyệt đối.","Cách ly thời gian (mùa vụ) — thuộc nhóm cách ly trước hợp tử.","Cách ly cơ học — thuộc nhóm cách ly sau hợp tử.","Cách ly tập tính — do con lai bất thụ."],"ans":1,"exp":"Sự lệch pha về mùa sinh sản ngăn cản giao phối dù sống chung một sinh cảnh $\\rightarrow$ cách ly thời gian (trước hợp tử)."},{"id":"MCQ-PO-095","topic":"population","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Cách ly Sinh sản","q":"Hai loài chim gõ kiến sống chung một khu rừng nhưng có điệu múa ve vãn và tiếng hót tán tỉnh khác nhau khiến con cái loài này không đáp lại con đực loài kia. Đây là:","opts":["Cách ly tập tính (trước hợp tử).","Cách ly địa lý.","Con lai giảm sức sống (sau hợp tử).","Cách ly nơi ở (trước hợp tử)."],"ans":0,"exp":"Tín hiệu giao phối đặc trưng (tiếng hót, vũ điệu, mùi pheromone) giúp nhận diện đúng bạn tình cùng loài và ngăn lai khác loài $\\rightarrow$ cách ly tập tính."},{"id":"MCQ-PO-096","topic":"population","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Hình thành Loài","q":"Tại sao quá trình hình thành loài bằng con đường cách ly sinh thái (cùng khu địa lý) diễn ra thuận lợi hơn ở những loài ít di chuyển (như côn trùng bám cây ký chủ, thực vật) so với động vật di cư xa?","opts":["Vì côn trùng có kích thước hệ gen lớn hơn động vật có xương sống.","Vì không chịu sự tác động của chọn lọc tự nhiên.","Vì các nhóm cá thể chuyên hóa vào các ổ sinh thái khác nhau ít có cơ hội gặp gỡ giao phối ngẫu nhiên với nhóm khác, tạo điều kiện cách ly dần dòng gen.","Vì các loài ít di chuyển luôn sinh sản vô tính."],"ans":2,"exp":"Ít di động giúp sự phân chia ổ sinh thái (cây ký chủ, loại đất, tầng nước) giảm tiếp xúc giao phối giữa các tiểu quần thể, hỗ trợ quá trình phân hóa loài tại chỗ."},{"id":"MCQ-PO-097","topic":"population","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Hình thành Loài","q":"Cơ chế hình thành loài bằng con đường lai xa kết hợp đa bội hóa rất phổ biến ở thực vật nhưng cực kỳ hiếm gặp ở động vật bậc cao là vì:","opts":["ADN của động vật không chứa phân tử đường deoxyribose.","Động vật không có tơ phân bào trong nguyên phân.","Thực vật không bao giờ xảy ra cách ly sau hợp tử.","Động vật thường có cơ chế xác định giới tính bằng cặp NST giới tính (XY, ZW) dễ bị rối loạn cân bằng giới tính khi đa bội hóa và ít có sinh sản sinh dưỡng hỗ trợ lúc đầu."],"ans":3,"exp":"Động vật bậc cao có hệ NST giới tính nhạy cảm với đa bội hóa và cấu tạo cơ quan phức tạp nên thể đa bội thường gây rối loạn phát triển và bất thụ."},{"id":"MCQ-PO-098","topic":"population","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Tiến hóa Phân tử & Đồng hồ phân tử","q":"Khái niệm 'đồng hồ phân tử' trong sinh học tiến hóa hiện đại dựa trên nguyên lý nào sau đây?","opts":["Số lượng nhiễm sắc thể tăng gấp đôi sau mỗi $1$ triệu năm.","Nhịp tim trung bình của mọi loài động vật có vú là giống hệt nhau.","Một số vùng trình tự ADN hoặc protein tiến hóa trung tính tích lũy các sai khác thay thế nucleotit/axit amin với tốc độ xấp xỉ hằng định theo thời gian.","Mọi đột biến gây chết đều xuất hiện vào cùng một thời điểm địa chất."],"ans":2,"exp":"Theo Kimura (thuyết tiến hóa trung tính), tốc độ thay thế các biến dị trung tính bằng chính tốc độ đột biến trung tính hàng năm, giúp ước lượng thời điểm phân ly tổ tiên giữa 2 loài."},{"id":"MCQ-PO-099","topic":"population","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Tiến hóa Phân tử","q":"So sánh trình tự axit amin của chuỗi hemoglobin $\\beta$ ($146$ axit amin) ở người với một số loài thu được số axit amin sai khác so với người: Khỉ Gôrila khác $1$, Khỉ Rhesus khác $8$, Chó khác $15$, Chim khác $45$, Cá mút đá khác $125$. Thứ tự quan hệ họ hàng từ GẦN ĐẾN XA nhất đối với loài người là:","opts":["Gôrila $\\rightarrow$ Khỉ Rhesus $\\rightarrow$ Chó $\\rightarrow$ Chim $\\rightarrow$ Cá mút đá.","Cá mút đá $\\rightarrow$ Chim $\\rightarrow$ Chó $\\rightarrow$ Gôrila.","Chó $\\rightarrow$ Gôrila $\\rightarrow$ Khỉ Rhesus $\\rightarrow$ Chim.","Khỉ Rhesus $\\rightarrow$ Gôrila $\\rightarrow$ Chim $\\rightarrow$ Chó."],"ans":0,"exp":"Số sai khác phân tử (axit amin hoặc nucleotit) càng ít thì thời điểm tách khỏi tổ tiên chung càng gần, tức quan hệ họ hàng càng thân thuộc."},{"id":"MCQ-PO-100","topic":"population","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Quần thể Ngẫu phối & Liên kết gen","q":"Xét $2$ cặp gen liên kết hoàn toàn trên một cặp NST thường. Một quần thể khởi đầu $P$ gồm $100\\%$ cá thể có kiểu gen dị hợp chéo $\\frac{Ab}{aB}$. Khi quần thể này ngẫu phối qua nhiều thế hệ (không hoán vị gen, không chọn lọc), cấu trúc di truyền đạt cân bằng sẽ là:","opts":["$100\\% \\frac{Ab}{aB}$ qua mọi thế hệ.","$0.25 AABB + 0.50 AaBb + 0.25 aabb = 1$.","$0.25 \\frac{Ab}{Ab} + 0.50 \\frac{Ab}{aB} + 0.25 \\frac{aB}{aB} = 1$.","$0.0625 \\frac{AB}{AB} + \\dots$ (tất cả $10$ kiểu gen)."],"ans":2,"exp":"Vì liên kết hoàn toàn ($f=0$), mỗi cá thể chỉ tạo $0.5 \\underline{Ab} : 0.5 \\underline{aB}$. Coi như $2$ alen giả định ngẫu phối ngay ở $F_1$ tạo $0.25 \\frac{Ab}{Ab} : 0.50 \\frac{Ab}{aB} : 0.25 \\frac{aB}{aB}$."},{"id":"MCQ-PO-101","topic":"population","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Quần thể tự phối qua N thế hệ","q":"Một quần thể thực vật có $0.2 AA + 0.8 Aa = 1$ tự thụ phấn liên tiếp. Tỉ lệ kiểu gen đồng hợp $AA$ tiến dần về giới hạn nào khi số thế hệ $n \\rightarrow \\infty$?","opts":["$0.60$.","$0.80$.","$0.50$.","$0.40$."],"ans":0,"exp":"Khi $n \\rightarrow \\infty$, dị hợp $Aa \\rightarrow 0$, nửa số dị hợp ban đầu ($0.8/2 = 0.4$) dồn vào $AA$, nửa dồn vào $aa$: $AA \\rightarrow 0.2 + 0.4 = 0.60$ (chính bằng $p(A)$) và $aa \\rightarrow 0.40$ (bằng $q(a)$)."},{"id":"MCQ-PO-102","topic":"population","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Tần số Alen & Đa bội","q":"Một quần thể thực vật tứ bội ($4n$) có cấu trúc kiểu gen gồm $0.3 AAaa + 0.5 Aaaa + 0.2 aaaa = 1$. Tần số alen $A$ và tần số alen $a$ trong quần thể này lần lượt là:","opts":["$p(A) = 0.275$ và $q(a) = 0.725$.","$p(A) = 0.250$ và $q(a) = 0.750$.","$p(A) = 0.400$ và $q(a) = 0.600$.","$p(A) = 0.300$ và $q(a) = 0.700$."],"ans":0,"exp":"Trong mỗi kiểu gen $4n$ có $4$ bản sao alen: $p(A) = 0.3 \\times \\frac{2}{4} + 0.5 \\times \\frac{1}{4} = 0.15 + 0.125 = 0.275 \\Rightarrow q(a) = 1 - 0.275 = 0.725$."},{"id":"MCQ-PO-103","topic":"population","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Thể Tứ bội & Ngẫu phối","q":"Một quần thể thực vật tứ bội ($4n$) có cấu trúc $0.6 AAaa + 0.4 Aaaa = 1$ tiến hành giảm phân bình thường tạo giao tử $2n$ và giao phấn ngẫu nhiên. Tỉ lệ cây mang kiểu gen đồng hợp lặn ($aaaa$) ở thế hệ $F_1$ là:","opts":["$12.25\\%$ ($0.1225$).","$16.0\\%$ ($0.16$).","$9.0\\%$ ($0.09$).","$4.0\\%$ ($0.04$)."],"ans":2,"exp":"Tỉ lệ giao tử $aa$ tạo từ quần thể $= 0.6 \\times \\frac{1}{6} + 0.4 \\times \\frac{1}{2} = 0.1 + 0.2 = 0.3$. Ngẫu phối tạo đồng hợp lặn $aaaa = (0.3)^2 = 0.09 = 9.0\\%$."},{"id":"MCQ-PO-104","topic":"population","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Động học Quần thể & Sức chứa Môi trường","q":"Trong tự nhiên, quần thể thỏ rừng Bắc Mỹ (*Lepus americanus*) và mèo rừng (*Lynx canadensis*) đều biểu hiện biến động số lượng cá thể lặp lại khá đều đặn với chu kỳ khoảng $9 - 11$ năm. Kiểu biến động số lượng này thuộc loại nào?","opts":["Tăng trưởng theo hàm số mũ không giới hạn.","Cân bằng Hardy-Weinberg tuyệt đối không đổi số lượng.","Biến động số lượng theo chu kỳ (do tương tác vật ăn thịt - con mồi và nguồn thức ăn thực vật).","Biến động số lượng không theo chu kỳ do thiên tai bất thường."],"ans":2,"exp":"Chu kỳ $9-11$ năm giữa thỏ tuyết và linh miêu là ví dụ kinh điển về biến động số lượng theo chu kỳ nhiều năm do mật độ và quan hệ dinh dưỡng."},{"id":"MCQ-PO-105","topic":"population","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Tiến hóa & Cạnh tranh Sinh học","q":"Hiện tượng hai loài có ổ sinh thái trùng lặp hoàn toàn không thể cùng tồn tại ổn định lâu dài trong một sinh cảnh hạn chế nguồn sống được phát biểu thành:","opts":["Định luật cân bằng Hardy-Weinberg.","Hiệu ứng sáng lập đảo của MacArthur.","Quy tắc phân ly độc lập của Mendel.","Nguyên lý loại trừ cạnh tranh của Gause."],"ans":3,"exp":"Thực nghiệm trên *Paramecium* của Gause chứng minh hai loài có ổ sinh thái hoàn toàn giống nhau sẽ cạnh tranh dẫn đến loài yếu bị loại trừ hoặc phải phân hóa ổ sinh thái."},{"id":"MCQ-PO-106","topic":"population","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Chọn lọc Tự nhiên & Đa hình cân bằng","q":"Ở các vùng sốt rét lưu hành tại châu Phi, người mang kiểu gen dị hợp $Hb^A Hb^S$ về bệnh hồng cầu hình liềm có ưu thế sinh tồn cao hơn cả $Hb^A Hb^A$ (dễ mắc sốt rét ác tính) và $Hb^S Hb^S$ (thiếu máu nặng). Đây là cơ chế duy trì alen $Hb^S$ trong quần thể gọi là:","opts":["Chọn lọc phân hóa hai cực.","Thoái hóa giống do tự phối.","Đa hình cân bằng nhờ ưu thế dị hợp tử.","Đột biến lặp đoạn nhiễm sắc thể."],"ans":2,"exp":"Khi thể dị hợp có giá trị thích nghi cao nhất, chọn lọc tự nhiên duy trì đồng thời cả hai alen trong quần thể ở trạng thái cân bằng ổn định (ưu thế dị hợp)."},{"id":"MCQ-PO-107","topic":"population","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Quần thể & Tác động Nhân tạo","q":"Ở loài giao phấn ngẫu nhiên, khi có hiện tượng tự thụ phấn kết hợp với ngẫu phối theo tỷ lệ $40\\%$ tự thụ phấn và $60\\%$ ngẫu phối trên xuất phát điểm $P: 100\\% Aa$, tỉ lệ kiểu gen dị hợp $Aa$ ở thế hệ $F_1$ là:","opts":["$0.40$.","$0.20$.","$0.50$.","$0.30$."],"ans":2,"exp":"Ở phần tự thụ ($40\\%$): $Aa$ cho $0.5 Aa$, đóng góp $0.4 \\times 0.5 = 0.20$. Ở phần ngẫu phối ($60\\%$, $p=q=0.5$): cho $2pq = 0.5 Aa$, đóng góp $0.6 \\times 0.5 = 0.30$. Tổng $Aa = 0.20 + 0.30 = 0.50$! (Tổng quát trên $P$ có $p=q=0.5$ ở $Aa$ thì luôn được $0.5$ ở $F_1$!)"},{"id":"MCQ-PO-108","topic":"population","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Ngẫu phối trên NST Giới tính X","q":"Ở ruồi giấm, mắt đỏ ($W$) trội hoàn toàn so với mắt trắng ($w$), gen trên vùng không tương đồng của NST X. Một quần thể $P$ có cấu trúc giới cái $0.2 X^W X^W + 0.6 X^W X^w + 0.2 X^w X^w$ và giới đực $0.6 X^W Y + 0.4 X^w Y$. Cho ngẫu phối, tỉ lệ ruồi ĐỰC mắt đỏ thu được ở $F_1$ tính trong tổng số ruồi $F_1$ là:","opts":["$15.0\\%$.","$25.0\\%$.","$30.0\\%$.","$50.0\\%$."],"ans":1,"exp":"Con đực $F_1$ nhận NST X từ mẹ và Y từ bố. Ở mẹ: $p_f(X^W) = 0.2 + 0.3 = 0.5$, $q_f(X^w) = 0.5$. Do đó $50\\%$ con đực $F_1$ mang $X^W Y$, chiếm $0.5 \\times 0.5 = 0.25 = 25.0\\%$ tổng số cá thể $F_1$."},{"id":"MCQ-PO-109","topic":"population","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Thống kê Di truyền Quần thể","q":"Trong một quần thể cây đậu ngẫu phối đang ở trạng thái cân bằng có $19\\%$ cây hoa đỏ đồng hợp và dị hợp? Không — đề chính xác: có $36\\%$ cây hoa trắng ($aa$) và $64\\%$ cây hoa đỏ ($A-$). Trong số các cây hoa đỏ ở quần thể này, tỉ lệ cây thuần chủng ($AA$) chiếm bao nhiêu phần trăm?","opts":["$37.5\\%$.","$25.0\\%$.","$16.0\\%$.","$48.0\\%$."],"ans":1,"exp":"Từ $aa = 0.36 \\Rightarrow q = 0.6$, $p = 0.4$. Suy ra $AA = 0.4^2 = 0.16$. Trong số các cây hoa đỏ ($0.64$), cây thuần chủng $AA$ chiếm $\\frac{0.16}{0.64} = 0.25 = 25.0\\%$."},{"id":"MCQ-PO-110","topic":"population","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Tiến hóa Chọn lọc Giới tính","q":"Đuôi công đực sặc sỡ cồng kềnh dù khiến con đực dễ bị thú săn mồi phát hiện nhưng vẫn được duy trì và tiến hóa qua nhiều thế hệ là kết quả của:","opts":["Đột biến xôma không di truyền.","Hiệu ứng thắt cổ chai do cháy rừng.","Cách ly cơ học giữa các loài công.","Chọn lọc giới tính (ưu thế thu hút bạn tình giúp tăng thành công sinh sản của con đực)."],"ans":3,"exp":"Chọn lọc giới tính (cạnh tranh bạn tình và sự lựa chọn của con cái) thúc đẩy các đặc điểm tăng xác suất giao phối dù có thể làm giảm nhẹ khả năng lẩn trốn kẻ thù."},{"id":"MCQ-PO-111","topic":"population","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Phả hệ & Quần thể","q":"Tần suất bệnh xơ nang (gen lặn $a$ trên NST thường) trong quần thể người cân bằng là $1/2500$. Người ta chọn ngẫu nhiên $1$ người phụ nữ bình thường không rõ phả hệ kết hôn với $1$ người đàn ông đã biết chắc chắn có kiểu gen dị hợp $Aa$. Xác suất để con đầu lòng của họ mắc bệnh xơ nang xấp xỉ:","opts":["$\\frac{1}{102}$ ($\\approx 0.98\\%$).","$\\frac{1}{2500}$.","$\\frac{1}{50}$.","$\\frac{1}{200}$."],"ans":0,"exp":"$q^2 = 1/2500 \\Rightarrow q = 1/50 = 0.02$. Xác suất người phụ nữ bình thường mang gen bệnh ($Aa$) là $\\frac{2q}{1+q} = \\frac{0.04}{1.02} = \\frac{2}{51}$. Chồng là $Aa$ ($100\\%$), vậy con bệnh ($aa$) $= 1 \\times \\frac{2}{51} \\times \\frac{1}{4} = \\frac{1}{102}$."},{"id":"MCQ-PO-112","topic":"population","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Đa dạng sinh học & Tiến hóa","q":"Phát biểu nào sau đây đúng về vai trò của chọn lọc tự nhiên đối với kiểu hình và alen lặn có hại?","opts":["Chọn lọc tự nhiên có tốc độ loại bỏ alen trội có hại NHANH hơn nhiều so với alen lặn có hại cùng cường độ tác động.","Alen lặn có hại luôn bị chọn lọc loại bỏ sạch sẽ chỉ sau $1$ thế hệ.","Chọn lọc tự nhiên không thể làm thay đổi tần số các kiểu gen trong quần thể.","Chọn lọc tự nhiên trực tiếp làm phát sinh các đột biến có lợi theo nhu cầu cá thể."],"ans":0,"exp":"Alen trội có hại biểu hiện ở cả thể đồng hợp trội và dị hợp nên mọi bản sao đều bị phơi bày trước chọn lọc; ngược lại alen lặn có hại ẩn nấp trong thể dị hợp khi $q$ nhỏ."},{"id":"MCQ-PO-113","topic":"population","level":"adv","levelText":"🟡 Nâng cao","subtopic":"Quần thể & Tương tác Gen","q":"Ở một loài hoa, màu đỏ hình thành khi có cả 2 alen trội $A$ và $B$ ($A-B-$), các kiểu gen còn lại cho hoa trắng ($2$ cặp gen phân ly độc lập). Trong một quần thể ngẫu phối cân bằng cả $2$ locus với $p(A) = 0.5$ và $p(B) = 0.5$, tỉ lệ cây hoa trắng trong quần thể là:","opts":["$25.00\\%$.","$43.75\\%$.","$56.25\\%$.","$75.00\\%$."],"ans":1,"exp":"Tại cân bằng: $A- = 1 - 0.5^2 = 0.75$; $B- = 0.75$. Hoa đỏ $A-B- = 0.75 \\times 0.75 = 0.5625$. Suy ra hoa trắng $= 1 - 0.5625 = 0.4375 = 43.75\\%$."},{"id":"MCQ-PO-114","topic":"population","level":"hsg","levelText":"🔴 HSG Tỉnh","subtopic":"Chọn lọc chống Alen lặn liên tục","q":"Ở một quần thể ngẫu phối, thế hệ xuất phát $P$ có cấu trúc $0.36 AA + 0.48 Aa + 0.16 aa = 1$. Giả sử kiểu gen đồng hợp lặn $aa$ bị chết ở giai đoạn phôi (giá trị thích nghi $W_{aa}=0$, còn $W_{AA}=W_{Aa}=1$) ở mọi thế hệ. Tỉ lệ kiểu gen đồng hợp lặn $aa$ ở thế hệ hợp tử $F_2$ bằng bao nhiêu?","opts":["$\\frac{4}{49}$ ($\\approx 8.16\\%$).","$\\frac{4}{81}$ ($\\approx 4.94\\%$).","$\\frac{9}{100}$ ($9.00\\%$).","$\\frac{1}{25}$ ($4.00\\%$)."],"ans":1,"exp":"Ở $P$ trưởng thành sau khi chết $aa$: $p_0 = 5/7, q_0 = 2/7 \\Rightarrow F_1$ hợp tử có $aa = (2/7)^2 = 4/49$, rồi $aa$ chết làm $F_1$ trưởng thành có $q_1 = \\frac{q_0}{1 + q_0} = \\frac{2/7}{9/7} = \\frac{2}{9}$. Ngẫu phối tạo hợp tử $F_2$ có $aa = (\\frac{2}{9})^2 = \\frac{4}{81}$."},{"id":"MCQ-PO-115","topic":"population","level":"hsg","levelText":"🔴 HSG Tỉnh","subtopic":"Ưu thế Dị hợp tử (Chọn lọc cân bằng)","q":"Trong một quần thể ngẫu phối kích thước rất lớn, giá trị thích nghi của $3$ kiểu gen đối với một bệnh nhiệt đới lần lượt là: $W_{AA} = 0.80$ ($s_1=0.2$), $W_{Aa} = 1.00$, $W_{aa} = 0.60$ ($s_2=0.4$). Khi đạt cân bằng chọn lọc ổn định, tần số alen $a$ ($\\hat{q}$) trong quần thể sẽ duy trì ở giá trị nào?","opts":["$\\frac{1}{3}$ ($\\approx 0.333$).","$0.250$.","$\\frac{2}{3}$ ($\\approx 0.667$).","$0.500$."],"ans":0,"exp":"Khi dị hợp có ưu thế ($W_{Aa}=1 > W_{AA}, W_{aa}$), tần số alen cân bằng là $\\hat{q} = \\frac{s_1}{s_1 + s_2} = \\frac{0.2}{0.2 + 0.4} = \\frac{1}{3}$ (và $\\hat{p} = \\frac{2}{3}$)."},{"id":"MCQ-PO-116","topic":"population","level":"hsg","levelText":"🔴 HSG Tỉnh","subtopic":"Tốc độ Chọn lọc một Thế hệ","q":"Một quần thể động vật ở thế hệ xuất phát $P$ có $0.25 AA + 0.50 Aa + 0.25 aa = 1$ ($p_0 = q_0 = 0.5$). Giá trị thích nghi của các kiểu gen là $W_{AA} = 1$, $W_{Aa} = 1$, $W_{aa} = 0.4$ (hệ số chọn lọc $s = 0.6$). Tần số alen $a$ ở các cá thể trưởng thành sống sót của thế hệ $P$ (và trong giao tử truyền sang $F_1$) là:","opts":["$0.350$.","$\\frac{7}{17}$ ($\\approx 0.412$).","$\\frac{1}{3}$ ($\\approx 0.333$).","$\\frac{5}{17}$ ($\\approx 0.294$)."],"ans":1,"exp":"Sức sống trung bình quần thể $\\bar{w} = 0.25(1) + 0.50(1) + 0.25(0.4) = 0.85$. Tỷ lệ sống sót sau chọn lọc: $AA = \\frac{0.25}{0.85}$, $Aa = \\frac{0.50}{0.85}$, $aa = \\frac{0.10}{0.85}$. Tần số $q' = \\frac{0.5(0.50) + 0.10}{0.85} = \\frac{0.35}{0.85} = \\frac{7}{17}$."},{"id":"MCQ-PO-117","topic":"population","level":"hsg","levelText":"🔴 HSG Tỉnh","subtopic":"Tự thụ phấn kết hợp Loại bỏ Lặn","q":"Một quần thể thực vật tự thụ phấn bắt buộc có cấu trúc các cây trưởng thành ở $P$ là $0.4 AA + 0.6 Aa = 1$. Biết hạt mang kiểu gen đồng hợp lặn $aa$ không nảy mầm được ở mọi thế hệ. Tỉ lệ hạt $aa$ bị chết (tỉ lệ nảy mầm hỏng) ở hợp tử thế hệ $F_2$ là bao nhiêu?","opts":["$\\frac{1}{12}$ ($\\approx 8.33\\%$).","$\\frac{3}{34}$ ($\\approx 8.82\\%$).","$\\frac{6}{17}$ ($\\approx 35.29\\%$).","$0.15$ ($15.0\\%$)."],"ans":1,"exp":"$F_1$ hợp tử: $0.55 AA : 0.30 Aa : 0.15 aa$. Loại $aa$, $F_1$ trưởng thành gồm $\\frac{11}{17} AA + \\frac{6}{17} Aa$. Tự thụ phấn $F_1$ tạo $F_2$ có tỉ lệ hạt chết $aa = \\frac{6}{17} \\times \\frac{1}{4} = \\frac{3}{34}$."},{"id":"MCQ-PO-118","topic":"population","level":"hsg","levelText":"🔴 HSG Tỉnh","subtopic":"Di truyền Liên kết X qua nhiều Thế hệ","q":"Xét một gen có $2$ alen $A, a$ nằm trên vùng không tương đồng của NST X. Giả sử một quần thể hỗn hợp được tạo thành từ $100\\%$ con cái đồng hợp trội ($X^A X^A$, $q_f = 0$) và $100\\%$ con đực mang alen lặn ($X^a Y$, $q_m = 1$), tỉ lệ đực:cái luôn là $1:1$. Sau khi ngẫu phối rất nhiều thế hệ đến trạng thái cân bằng, tần số alen $a$ chung trong quần thể tiến về giá trị nào?","opts":["$\\frac{2}{3}$ ($\\approx 0.667$).","$\\frac{1}{3}$ ($\\approx 0.333$).","$\\frac{1}{2}$ ($0.500$).","$\\frac{1}{4}$ ($0.250$)."],"ans":1,"exp":"Do giới cái mang $2$ NST X và giới đực mang $1$ NST X nên tổng số NST X có tỉ lệ đóng góp $2:1$. Tần số cân bằng $q^* = \\frac{2 q_f + q_m}{3} = \\frac{2(0) + 1}{3} = \\frac{1}{3}$."},{"id":"MCQ-PO-119","topic":"population","level":"hsg","levelText":"🔴 HSG Tỉnh","subtopic":"Di truyền Liên kết X qua nhiều Thế hệ","q":"Với quần thể khởi đầu như câu trên ($P$: $100\\%$ cái $X^A X^A$, $100\\%$ đực $X^a Y$, tỉ lệ đực:cái $1:1$). Hiệu số tần số alen giữa giới đực và giới cái $|q_m - q_f|$ ở thế hệ $F_2$ là bao nhiêu?","opts":["$0.50$.","$0.00$.","$0.25$.","$0.125$."],"ans":2,"exp":"$P$: $q_{f0}=0, q_{m0}=1 \\Rightarrow |\\Delta_0| = 1$. Sang $F_1$: $X^A X^a$ ($q_{f1}=0.5$) và $X^A Y$ ($q_{m1}=0$), $|\\Delta_1| = 0.5$. Sang $F_2$: $q_{f2} = \\frac{0.5+0}{2} = 0.25$, $q_{m2} = q_{f1} = 0.50$. Hiệu số $|q_{m2} - q_{f2}| = |0.50 - 0.25| = 0.25$ (giảm đi một nửa sau mỗi thế hệ và đổi dấu)."},{"id":"MCQ-PO-120","topic":"population","level":"hsg","levelText":"🔴 HSG Tỉnh","subtopic":"Tương tác Di-nhập gen & Chọn lọc","q":"Quần thể bản địa ở đất liền rất lớn duy trì $p_m(A) = 0.2$. Một quần thể nhỏ trên đảo đang có $p_0(A) = 0.7$, mỗi thế hệ nhận dòng nhập cư từ đất liền với tỷ lệ $m = 0.1$ ($10\\%$). Ngay sau $2$ thế hệ chỉ chịu tác động của dòng nhập cư đều đặn này (giả sử đảo ngẫu phối không chọn lọc), tần số alen $A$ trên đảo sẽ là:","opts":["$0.500$.","$0.650$.","$0.605$.","$0.550$."],"ans":2,"exp":"Công thức lặp $p_n - p_m = (1-m)^n (p_0 - p_m)$. Với $n=2, m=0.1, p_0=0.7, p_m=0.2$: $p_2 = 0.2 + (0.9)^2(0.7 - 0.2) = 0.2 + 0.81 \\times 0.5 = 0.2 + 0.405 = 0.605$."},{"id":"MCQ-PO-121","topic":"population","level":"hsg","levelText":"🔴 HSG Tỉnh","subtopic":"Cân bằng Liên kết & Hoán vị gen ($D$)","q":"Trong một quần thể ngẫu phối lớn, xét $2$ gen $A/a$ và $B/b$ cùng nằm trên một cặp NST thường với tần số hoán vị gen $r = 0.20$. Ở thế hệ $P$, tần số các giao tử là $\\underline{AB} = 0.4$, $\\underline{ab} = 0.4$, $\\underline{Ab} = 0.1$, $\\underline{aB} = 0.1$ (tức $p_A = p_B = 0.5$, độ mất cân bằng liên kết $D_0 = 0.4 - 0.25 = 0.15$). Sau $1$ thế hệ ngẫu phối ($F_1$), tần số giao tử $\\underline{AB}$ do thế hệ $F_1$ tạo ra là bao nhiêu?","opts":["$0.35$.","$0.37$.","$0.25$.","$0.40$."],"ans":1,"exp":"Theo phương trình $D_{n+1} = (1 - r) D_n$: $D_1 = (1 - 0.20) \\times 0.15 = 0.12$. Khi đó $f(\\underline{AB})_1 = p_A p_B + D_1 = 0.25 + 0.12 = 0.37$."},{"id":"MCQ-PO-122","topic":"population","level":"hsg","levelText":"🔴 HSG Tỉnh","subtopic":"Cân bằng Đa bội & Giao tử bất thường","q":"Ở một loài thực vật tứ bội ($4n$), xét quần thể $P$ có $100\\%$ cây mang kiểu gen $AAaa$. Giả sử hạt phấn mang $2$ alen lặn ($aa$) hoàn toàn mất khả năng thụ tinh (chỉ hạt phấn $AA$ và $Aa$ tham gia thụ tinh), trong khi mọi noãn $2n$ đều thụ tinh bình thường. Khi cho $P$ tự thụ phấn thu được $F_1$, tỉ lệ cây có kiểu hình trội ($A---$) có kiểu gen $AAAa$ ở $F_1$ là bao nhiêu?","opts":["$\\frac{1}{5}$ ($20.0\\%$).","$\\frac{8}{36}$ ($\\approx 22.22\\%$).","$\\frac{4}{15}$ ($\\approx 26.67\\%$).","$\\frac{2}{5}$ ($40.0\\%$."],"ans":2,"exp":"Kiểu gen $AAaa$ tạo giao tử chuẩn $\\frac{1}{6}AA : \\frac{4}{6}Aa : \\frac{1}{6}aa$. Do hạt phấn $aa$ chết nên hạt phấn hữu thụ chỉ còn $\\frac{1}{5}AA : \\frac{4}{5}Aa$. Noãn vẫn là $\\frac{1}{6}AA : \\frac{4}{6}Aa : \\frac{1}{6}aa$. Tổ hợp $AAAa = \\frac{1}{5}AA(\\text{đực}) \\times \\frac{4}{6}Aa(\\text{cái}) + \\frac{4}{5}Aa(\\text{đực}) \\times \\frac{1}{6}AA(\\text{cái}) = \\frac{4}{30} + \\frac{4}{30} = \\frac{8}{30} = \\frac{4}{15}$."},{"id":"MCQ-PO-123","topic":"population","level":"hsg","levelText":"🔴 HSG Tỉnh","subtopic":"Quần thể Tự phối & Đa hình Nhóm máu","q":"Một quần thể động vật có vú có $100\\%$ cá thể thế hệ $P$ mang kiểu gen $Aa$. Do biến cố, quần thể chuyển sang giao phối cận huyết hoàn toàn theo cặp anh-chị-em ruột? Không: giả sử ở thế hệ $P$ có cấu trúc $0.25 AA + 0.50 Aa + 0.25 aa$ thực hiện GIAO PHỐI CÓ LỰA CHỌN ĐỒNG HÌNH: $AA$ chỉ giao phối với $AA$, $Aa$ chỉ giao phối với $Aa$, $aa$ chỉ giao phối với $aa$ (cơ cấu kiểu gen khác nhau không giao phối). Sau $1$ thế hệ ($F_1$), tỉ lệ kiểu gen $Aa$ là bao nhiêu?","opts":["$0.375$.","$0.125$.","$0.500$.","$0.250$."],"ans":3,"exp":"$AA$ ($0.25$) tự giao tạo $0.25 AA$; $aa$ ($0.25$) tự giao tạo $0.25 aa$; nhóm $Aa$ ($0.50$) tự giao với $Aa$ ($Aa \\times Aa \\rightarrow 0.25 AA + 0.50 Aa + 0.25 aa$) nên đóng góp $0.50 \\times 0.50 = 0.25 Aa$. Kết quả ở $F_1$ tương đương tự thụ phấn: $0.375 AA + 0.250 Aa + 0.375 aa$!"},{"id":"MCQ-PO-124","topic":"population","level":"hsg","levelText":"🔴 HSG Tỉnh","subtopic":"Hệ số Nội phối $F$ (Inbreeding)","q":"Trong một quần thể ngẫu phối có pha tạp giao phối gần với hệ số nội phối chung $F = 0.25$, biết tần số các alen $p(A) = 0.6$, $q(a) = 0.4$. Áp dụng công thức quần thể có nội phối ($AA = p^2 + pqF$; $Aa = 2pq(1-F)$; $aa = q^2 + pqF$), tần số kiểu gen dị hợp $Aa$ trong quần thể là:","opts":["$0.36$.","$0.48$.","$0.22$.","$0.42$."],"ans":0,"exp":"Thay số: $2pq = 2 \\times 0.6 \\times 0.4 = 0.48$. Tần số dị hợp $Aa = 2pq(1 - F) = 0.48 \\times (1 - 0.25) = 0.36$ (giảm $25\\%$ so với $0.48$ của ngẫu phối thuần túy)."},{"id":"MCQ-PO-125","topic":"population","level":"hsg","levelText":"🔴 HSG Tỉnh","subtopic":"Hệ số Nội phối $F$ (Inbreeding)","q":"Tiếp nối bài toán hệ số nội phối trên ($F = 0.25$, $p = 0.6$, $q = 0.4$), hiệu số giữa tỉ lệ kiểu gen đồng hợp trội $AA$ và đồng hợp lặn $aa$ trong quần thể là bao nhiêu?","opts":["$0.14$.","$0.22$.","$0.42$.","$0.20$."],"ans":3,"exp":"$f(AA) = 0.6^2 + (0.6)(0.4)(0.25) = 0.36 + 0.06 = 0.42$; $f(aa) = 0.4^2 + 0.06 = 0.22$. Hiệu số $f(AA) - f(aa) = 0.42 - 0.22 = 0.20$ (bằng đúng $p^2 - q^2 = p - q$, không phụ thuộc $F$!)."},{"id":"MCQ-PO-126","topic":"population","level":"hsg","levelText":"🔴 HSG Tỉnh","subtopic":"Tác động Phiêu bạt Di truyền","q":"Trong một loài có $100$ quần thể nhỏ độc lập giống hệt nhau, mỗi quần thể đều khởi đầu với $p_0 = q_0 = 0.5$ và luôn duy trì kích thước hiệu quả không đổi $N_e = 25$ cá thể qua các thế hệ (không chọn lọc, không đột biến, không dòng gen). Theo thuyết phiêu bạt di truyền của Wright, khi $t \\rightarrow \\infty$, có khoảng bao nhiêu quần thể sẽ cố định alen $A$ ($p=1$) và phương sai tần số alen giữa các quần thể ở thế hệ $t=1$ bằng bao nhiêu?","opts":["Khoảng $25$ quần thể cố định $A$; phương sai $V_1(p) = 0.025$.","Không quần thể nào bị cố định alen; phương sai $V_1(p) = 0$.","Khoảng $50$ quần thể cố định $A$; phương sai $V_1(p) = \\frac{p_0 q_0}{2 N_e} = 0.005$.","Tất cả $100$ quần thể cố định $A$; phương sai $V_1(p) = 0.05$."],"ans":2,"exp":"Xác suất một alen trung tính đi đến cố định bằng đúng tần số ban đầu $p_0 = 0.5 \\Rightarrow 50$ quần thể cố định $A$. Phương sai lấy mẫu lưỡng bội 1 thế hệ là $V_1 = \\frac{p_0 q_0}{2 N_e} = \\frac{0.25}{50} = 0.005$."},{"id":"MCQ-PO-127","topic":"population","level":"hsg","levelText":"🔴 HSG Tỉnh","subtopic":"Tốc độ Thay đổi Tần số Alen dưới Chọn lọc","q":"Xét trường hợp đột biến tái diễn $A \\rightarrow a$ với tốc độ $u = 10^{-5}$ mỗi thế hệ, đồng thời kiểu gen $aa$ gây chết sớm ($W_{aa}=0, W_{AA}=W_{Aa}=1$, tức $s=1$). Ở trạng thái cân bằng đột biến – chọn lọc ($q^* \\approx \\sqrt{u/s}$), tần số alen lặn $q^*$ và tần số bệnh $q^{*2}$ tương ứng bằng bao nhiêu?","opts":["$q^* \\approx 3.16 \\times 10^{-4}$ và tần số bệnh $\\approx 10^{-7}$.","$q^* \\approx 3.16 \\times 10^{-3}$ và tần số bệnh $\\approx 10^{-5}$.","$q^* \\approx 10^{-5}$ và tần số bệnh $\\approx 10^{-10}$.","$q^* \\approx 10^{-2}$ và tần số bệnh $\\approx 10^{-4}$."],"ans":1,"exp":"Khi alen lặn gây chết cân bằng với đột biến $u$: mỗi thế hệ chọn lọc loại bỏ $q^2$ cá thể (tức $2q^2$ alen trên $2$ alen/người $\\rightarrow$ mức giảm $\\approx q^2$), cân bằng với mức sinh mới $u \\Rightarrow q^2 = u = 10^{-5} \\Rightarrow q^* = \\sqrt{10^{-5}} \\approx 3.16 \\times 10^{-3}$."},{"id":"MCQ-PO-128","topic":"population","level":"hsg","levelText":"🔴 HSG Tỉnh","subtopic":"Tốc độ Chọn lọc chống Alen Trội","q":"Xét bệnh Huntington do alen trội $A$ trên NST thường gây ra sau độ tuổi sinh sản (hay giả sử bệnh trội nặng khởi phát sớm làm $W_{AA}=W_{Aa}=0.5$ tương đương $s=0.5$, còn $W_{aa}=1$). Ở trạng thái cân bằng giữa đột biến $a \\rightarrow A$ với tốc độ $u = 2 \\times 10^{-6}$ và chọn lọc ($p^* \\approx u/s$), tần số kiểu gen mang alen bệnh ($2 p^*$) xấp xỉ:","opts":["$8 \\times 10^{-6}$.","$4 \\times 10^{-6}$.","$2 \\times 10^{-3}$.","$1 \\times 10^{-6}$."],"ans":0,"exp":"Với alen trội hiếm ($p \\ll 1$), hầu như toàn bộ cá thể bệnh là dị hợp $Aa$ ($2p$), mỗi cá thể bệnh có xác suất bị loại bỏ $s = 0.5$, đóng góp mức mất $p \\cdot s$ cân bằng với đột biến mới $u \\Rightarrow p^* \\approx \\frac{u}{s} = \\frac{2 \\times 10^{-6}}{0.5} = 4 \\times 10^{-6}$. Tỉ lệ người mang bệnh $Aa \\approx 2p^* = 8 \\times 10^{-6}$."},{"id":"MCQ-PO-129","topic":"population","level":"hsg","levelText":"🔴 HSG Tỉnh","subtopic":"Di truyền Quần thể & Bất đồng nhóm máu Rh","q":"Ở người, kháng nguyên Rh ($+$) do alen $R$ trội hoàn toàn so với $r$ (Rh$-$). Trong một quần thể cân bằng có $16\\%$ người có nhóm máu Rh($-$). Tai biến bất đồng nhóm máu mẹ-con xảy ra khi mẹ Rh($-$) ($rr$) mang thai con Rh($+$) ($Rr$). Xác suất một cặp vợ chồng ngẫu nhiên trong quần thể thuộc trường hợp 'mẹ $rr$, bố có $R$, và đứa con đầu lòng mang kiểu gen $Rr$' là bao nhiêu?","opts":["$16.0\\%$.","$13.44\\%$.","$9.6\\%$ ($0.096$).","$4.8\\%$."],"ans":2,"exp":"Từ $rr = 0.16 \\Rightarrow q(r) = 0.4$, $p(R) = 0.6$. Xác suất chọn được vợ $rr = q^2 = 0.16$. Để con mang $Rr$, mẹ $rr$ luôn cho $r$, nên chỉ cần tinh trùng từ bố ngẫu nhiên mang $R$ (tần số $p = 0.6$ trong toàn quần thể bố!). Vậy xác suất cần tìm $= 0.16 \\times 0.6 = 0.096 = 9.6\\%$."},{"id":"MCQ-PO-130","topic":"population","level":"hsg","levelText":"🔴 HSG Tỉnh","subtopic":"Quần thể Tự phối kết hợp Biến dị","q":"Một quần thể thực vật tự thụ phấn thế hệ $P$ có $0.3 AA + 0.4 Aa + 0.3 aa = 1$. Do điều kiện ngoại cảnh khắc nghiệt, ở mỗi thế hệ chỉ có $50\\%$ số cá thể $aa$ sống sót đến lúc ra hoa sinh sản (trong khi $AA$ và $Aa$ sống sót $100\\%$). Cấu trúc các cây đang ra hoa ở thế hệ $F_1$ xấp xỉ là:","opts":["$0.45 AA + 0.25 Aa + 0.30 aa$.","$0.50 AA + 0.20 Aa + 0.30 aa$.","$\\frac{40}{80} AA + \\frac{20}{80} Aa + \\frac{20}{80} aa$ ($0.50 AA + 0.25 Aa + 0.25 aa$).","$0.40 AA + 0.20 Aa + 0.40 aa$."],"ans":2,"exp":"Từ $P$ ra hoa ($0.3 AA + 0.4 Aa + 0.3 aa$)? Khoan: đọc kỹ! Ở thế hệ $P$ giả sử đã đến giai đoạn ra hoa là $0.3 AA : 0.4 Aa : 0.3 aa$. Tự thụ tạo hợp tử $F_1$: $AA = 0.3+0.1 = 0.4$, $Aa = 0.2$, $aa = 0.3+0.1 = 0.4$. Ở $F_1$ chỉ $50\\%$ số $aa$ sống sót $\\rightarrow$ còn $0.4 AA : 0.2 Aa : 0.2 aa$, tổng $= 0.8$. Chia chuẩn hóa cho $0.8$: $0.50 AA + 0.25 Aa + 0.25 aa$! Tuyệt đẹp!"},{"id":"MCQ-PO-131","topic":"population","level":"hsg","levelText":"🔴 HSG Tỉnh","subtopic":"Phân bố Tần số Alen & Đa dạng di truyền ($H_e$)","q":"Chỉ số dị hợp tử kỳ vọng $H_e = 1 - \\sum_{i=1}^k p_i^2$ đo lường sự đa dạng di truyền tại một locus đa alen trong quần thể ngẫu phối. Với một gen có $4$ alen $A_1, A_2, A_3, A_4$ có tần số lần lượt là $0.4, 0.3, 0.2, 0.1$, giá trị đa dạng gen $H_e$ (tỉ lệ dị hợp tử chung) của quần thể là:","opts":["$0.70$.","$0.60$.","$0.30$.","$0.75$."],"ans":0,"exp":"Tổng tỉ lệ đồng hợp $= 0.4^2 + 0.3^2 + 0.2^2 + 0.1^2 = 0.16 + 0.09 + 0.04 + 0.01 = 0.30$. Suy ra tổng tỉ lệ dị hợp $H_e = 1 - 0.30 = 0.70$."},{"id":"MCQ-PO-132","topic":"population","level":"hsg","levelText":"🔴 HSG Tỉnh","subtopic":"Hiệu ứng Wahlund khi Gộp Quần thể","q":"Xét $2$ quần thể tách biệt có kích thước bằng nhau: Quần thể $1$ cân bằng ở $p_1 = 0.8$, Quần thể $2$ cân bằng ở $p_2 = 0.2$. Nếu một nhà nghiên cứu gộp chung mẫu của $2$ quần thể lại xem như một quần thể hỗn hợp lớn ($\\bar{p} = 0.5$) thì lượng THIẾU HỤT thể dị hợp thực tế so với kỳ vọng Hardy-Weinberg ($2\\bar{p}\\bar{q} - \\bar{H}$, tức hiệu ứng Wahlund $= 2 \\text{Var}(p)$) bằng bao nhiêu?","opts":["$0.50$.","$0.18$.","$0.32$.","$0.09$."],"ans":1,"exp":"Dị hợp thực tế trung bình $= \\frac{2(0.8)(0.2) + 2(0.2)(0.8)}{2} = 0.32$. Dị hợp kỳ vọng tại $\\bar{p}=0.5$ là $2(0.5)(0.5) = 0.50$. Độ thiếu hụt Wahlund $= 0.50 - 0.32 = 0.18 = 2 \\times (0.3^2)$."},{"id":"MCQ-PO-133","topic":"population","level":"hsg","levelText":"🔴 HSG Tỉnh","subtopic":"Tương tác Hardy-Weinberg & Di truyền Chiều cao/Định lượng","q":"Ở một loài thực vật, chiều cao cây do $2$ cặp gen phân ly độc lập $A/a$ và $B/b$ tương tác cộng gộp quy định (cứ mỗi alen trội làm cây cao thêm $10\\text{ cm}$, cây $aabb$ cao $100\\text{ cm}$). Trong quần thể ngẫu phối cân bằng với $p(A) = 0.5$, $p(B) = 0.5$, tỉ lệ cây đạt chiều cao đúng $120\\text{ cm}$ là bao nhiêu?","opts":["$6.25\\%$ ($\\frac{1}{16}$).","$37.5\\%$ ($\\frac{3}{8}$).","$50.0\\%$ ($\\frac{1}{2}$).","$25.0\\%$ ($\\frac{1}{4}$)."],"ans":1,"exp":"Cây cao $120\\text{ cm}$ mang đúng $2$ alen trội ($100 + 2\\times 10 = 120$). Với $p_A=p_B=0.5$, phân phối $4$ alen tương đương nhị thức $(0.5+0.5)^4$: số tổ hợp có $2$ alen trội là $\\binom{4}{2}(0.5)^4 = 6/16 = 3/8 = 37.5\\%$."},{"id":"MCQ-PO-134","topic":"population","level":"hsg","levelText":"🔴 HSG Tỉnh","subtopic":"Kiểm định Phù hợp Hardy-Weinberg ($\\chi^2$)","q":"Khảo sát mẫu $1000$ cá thể trong một quần thể thực vật thu được: $160 AA$, $480 Aa$, $360 aa$. Khi kiểm định giả thuyết quần thể đang cân bằng Hardy-Weinberg bằng thống kê Chi-bình phương ($\\chi^2$), bậc tự do ($df$) của phép thử và giá trị $\\chi^2$ tính được lần lượt là:","opts":["$df = 1$ và $\\chi^2 = 0$.","$df = 1$ và $\\chi^2 = 3.84$.","$df = 2$ và $\\chi^2 = 5.99$.","$df = 2$ và $\\chi^2 = 0$."],"ans":0,"exp":"Từ mẫu tính được $p = \\frac{160 + 240}{1000} = 0.4$, $q = 0.6$. Kỳ vọng $E(AA)=160, E(Aa)=480, E(aa)=360$ khớp hoàn toàn thực tế nên $\\chi^2 = 0$. Vì ước lượng $1$ tham số độc lập $p$ từ $3$ nhóm kiểu hình ($k=3$), số bậc tự do $df = k - 1 - 1 = 1$."},{"id":"MCQ-PO-135","topic":"population","level":"hsg","levelText":"🔴 HSG Tỉnh","subtopic":"Thể Song nhị bội & Phép lai Quần thể","q":"Loài A ($2n=14$) lai xa với loài B ($2n=16$) tạo con lai bất thụ, sau đó gây đa bội hóa thành loài mới C có bộ NST $2n = 30$. Khi đánh giá cấu trúc cách ly của loài C với hai loài bố mẹ, điều gì xảy ra nếu cho loài C lai trở lại với loài A ($2n=14$)?","opts":["Loài C mang $2n=15$ NST nên kết hợp hoàn hảo với loài A.","Tạo hợp tử $3n = 22$ NST nhưng không thể giảm phân tạo giao tử cân bằng nên bất thụ (cách ly sau hợp tử).","Tạo con lai hữu thụ bình thường do có chung bộ NST của loài A.","Không thể thụ phấn được do hoa loài C luôn đóng kín."],"ans":1,"exp":"Loài C tạo giao tử $n_A + n_B = 7 + 8 = 15$ NST; loài A tạo giao tử $n_A = 7$. Con lai nhận $2n_A + n_B = 22$ NST (bộ $n_B$ đứng đơn chiếc), rối loạn tiếp hợp giảm phân nên bất thụ $\\rightarrow$ C là loài mới cách ly sinh sản với cả A và B."},{"id":"MCQ-PO-136","topic":"population","level":"hsg","levelText":"🔴 HSG Tỉnh","subtopic":"Quần thể Tự thụ phấn từ Thế hệ $F_k$","q":"Một quần thể thực vật tự thụ phấn bắt buộc. Người ta đo được ở thế hệ $F_3$ cấu trúc di truyền là $0.51 AA + 0.08 Aa + 0.41 aa = 1$. Thành phần kiểu gen ở thế hệ xuất phát $P$ ban đầu là bao nhiêu?","opts":["$0.23 AA + 0.64 Aa + 0.13 aa = 1$.","$0.27 AA + 0.56 Aa + 0.17 aa = 1$.","$0.31 AA + 0.48 Aa + 0.21 aa = 1$.","$0.35 AA + 0.40 Aa + 0.25 aa = 1$."],"ans":0,"exp":"Ở $F_3$: $Aa = H_0 \\times (1/2)^3 = 0.08 \\Rightarrow H_0 = 0.64$. Lượng dị hợp đã phân ly trong $3$ thế hệ $= 0.64 - 0.08 = 0.56$, chia đôi mỗi bên $0.28$. Vậy $AA_0 = 0.51 - 0.28 = 0.23$; $aa_0 = 0.41 - 0.28 = 0.13$. (Tổng $0.23+0.64+0.13=1$)."},{"id":"MCQ-PO-137","topic":"population","level":"hsg","levelText":"🔴 HSG Tỉnh","subtopic":"Giao phối chọn lọc & Sức sinh sản khác biệt","q":"Một quần thể ở thế hệ $P$ gồm $0.40 AA + 0.40 Aa + 0.20 aa = 1$. Giả sử nhóm kiểu hình trội ($A-$) chỉ ngẫu phối trong nhóm $A-$, nhóm lặn ($aa$) chỉ giao phối trong nhóm $aa$, nhưng mỗi cá thể thuộc nhóm $aa$ chỉ sinh được số con bằng $50\\%$ so với một cá thể thuộc nhóm $A-$. Tỉ lệ kiểu gen đồng hợp lặn $aa$ thu được trong tổng số con $F_1$ là:","opts":["$\\frac{1}{16}$ ($6.25\\%$).","$\\frac{5}{27}$ ($\\approx 18.52\\%$).","$\\frac{1}{6}$ ($\\approx 16.67\\%$).","$\\frac{1}{4}$ ($25.00\\%$)."],"ans":2,"exp":"Nhóm $A-$ (trọng số $0.8$) gồm $\\frac{1}{2}AA + \\frac{1}{2}Aa$ có $q=0.25$, khi ngẫu phối sinh $0.8 \\times (0.25)^2 = 0.05$ con $aa$. Nhóm $aa$ ($0.2$) có sức sinh sản $0.5$ nên đóng góp $0.2 \\times 0.5 = 0.10$ con $aa$. Tổng quy mô con $F_1 = 0.8(1) + 0.2(0.5) = 0.90$. Tỉ lệ $aa$ ở $F_1 = \\frac{0.05 + 0.10}{0.90} = \\frac{1}{6}$."},{"id":"MCQ-PO-138","topic":"population","level":"hsg","levelText":"🔴 HSG Tỉnh","subtopic":"Liên kết Giới tính & Tương tác NST thường","q":"Ở gà ($ZZ/ZW$), alen $B$ trên NST thường quy định lông đen trội hoàn toàn so với $b$ lông trắng; trên NST Z có gen $A$ trội hoàn toàn so với $a$ làm lông vằn (gà có $bb$ luôn lông trắng bất kể $A/a$). Một quần thể ngẫu phối cân bằng với $p(B) = 0.5$ và $p(Z^A) = 0.4$ (tỉ lệ gà trống $ZZ$ : gà mái $ZW = 1:1$). Tỉ lệ gà con lông ĐEN KHÔNG VẰN ($B- Z^a Z^a$ hoặc $B- Z^a W$) trong toàn quần thể là:","opts":["$18.0\\%$.","$36.0\\%$.","$27.0\\%$.","$45.0\\%$."],"ans":1,"exp":"Ở locus NST thường: $B- = 1 - 0.5^2 = 0.75$. Ở locus giới tính ($q(Z^a) = 0.6$): trống không vằn ($Z^a Z^a$) chiếm $0.6^2 = 0.36$ trong số trống; mái không vằn ($Z^a W$) chiếm $0.60$ trong số mái. Tỉ lệ không vằn chung $= 0.5(0.36) + 0.5(0.60) = 0.48$. Kết hợp 2 locus độc lập: $0.75 \\times 0.48 = 0.36 = 36.0\\%$."},{"id":"MCQ-PO-139","topic":"population","level":"hsg","levelText":"🔴 HSG Tỉnh","subtopic":"Phân tích Cây Phát sinh Chủng loại (Phylogenetics)","q":"Khi xây dựng cây phát sinh chủng loại theo phương pháp tối giản (Maximum Parsimony), nguyên tắc quyết định chọn cây tiến hóa tối ưu giữa nhiều cây giả thuyết là:","opts":["Luôn ưu tiên xếp các loài sống cùng môi trường nước thành một nhánh đơn ngành bất kể giải phẫu.","Chọn cây có số lượng nhánh phụ tối đa có thể.","Chọn cây không có bất kỳ cơ quan thoái hóa hay mất tính trạng nào.","Chọn cây đòi hỏi TỔNG SỐ SỰ KIỆN ĐỘT BIẾN / THAY ĐỔI TIẾN HÓA ÍT NHẤT giải thích được tất cả các trạng thái đặc điểm ở các loài hiện đại."],"ans":3,"exp":"Nguyên tắc tiết kiệm tối đa (Maximum Parsimony) giả định tự nhiên ưu tiên con đường giải thích cần ít bước biến đổi tiến hóa độc lập (và ít đảo ngược tiến hóa) nhất."},{"id":"MCQ-PO-140","topic":"population","level":"hsg","levelText":"🔴 HSG Tỉnh","subtopic":"Nhóm Đơn ngành, Cận ngành, Đa ngành","q":"Trong phân loại học tiến hóa (Cladistics), một nhóm phân loại học hợp lệ gọi là NHÓM ĐƠN NGÀNH (Monophyletic group / Clade) khi thỏa mãn điều kiện nào?","opts":["Tập hợp các loài có đặc điểm tương tự nhưng xuất phát từ các tổ tiên khác nhau (ví dụ động vật máu nóng gồm chim và thú).","Bao gồm tổ tiên chung nhưng bỏ sót một vài nhóm hậu duệ tiến hóa nhanh (ví dụ 'bò sát' nếu loại trừ chim).","Bao gồm một loài tổ tiên chung gần nhất và TẤT CẢ các loài hậu duệ bắt nguồn từ tổ tiên đó.","Chỉ bao gồm các loài đã tuyệt chủng hoàn toàn từ kỷ Creta."],"ans":2,"exp":"Nhóm đơn ngành chứa đúng tổ tiên chung + toàn bộ mọi hậu duệ của nó. Nếu bỏ sót chim khỏi lớp Bò sát sẽ thành nhóm cận ngành; gộp chim + thú thành 'động vật đẳng nhiệt' là nhóm đa ngành."},{"id":"MCQ-PO-141","topic":"population","level":"hsg","levelText":"🔴 HSG Tỉnh","subtopic":"Hệ số Thích nghi & Alen gây chết có điều kiện","q":"Ở một loài bọ cánh cứng, kiểu gen $AA$ có sức sống $100\\%$, $Aa$ có sức sống $80\\%$ ($s_{Aa}=0.2$), $aa$ có sức sống $50\\%$ ($s_{aa}=0.5$). Xuất phát từ $P$ có $0.25 AA + 0.50 Aa + 0.25 aa = 1$. Tần số alen $A$ ở các cá thể trưởng thành sống sót qua $1$ vòng chọn lọc này là bao nhiêu?","opts":["$\\frac{13}{31}$ ($\\approx 0.419$).","$\\frac{9}{15.5} = \\frac{18}{31}$ ($\\approx 0.581$).","$\\frac{20}{31}$ ($\\approx 0.645$).","$\\frac{1}{2}$ ($0.500$)."],"ans":1,"exp":"Sức sống trung bình $\\bar{w} = 0.25(1.0) + 0.50(0.8) + 0.25(0.5) = 0.25 + 0.40 + 0.125 = 0.775$. Tỷ trọng $AA = 0.25$, $Aa = 0.40$, $aa = 0.125$. Tần số $p' = \\frac{0.25 + 0.5(0.40)}{0.775} = \\frac{0.45}{0.775} = \\frac{450}{775} = \\frac{18}{31}$."},{"id":"MCQ-PO-142","topic":"population","level":"hsg","levelText":"🔴 HSG Tỉnh","subtopic":"Tự thụ phấn & Khả năng tạo Hạt khác biệt","q":"Một quần thể thực vật tự thụ phấn xuất phát $P$ gồm $0.2 AA + 0.8 Aa = 1$. Giả sử mọi cá thể đều nảy mầm sống $100\\%$, nhưng năng suất tạo hạt hữu thụ của cây $AA$ và $Aa$ gấp đôi cây $aa$ (hệ số sinh sản $1:1:0.5$). Thành phần kiểu gen thu được ở thế hệ $F_2$ là:","opts":["$\\frac{5}{9} AA + \\frac{2}{9} Aa + \\frac{2}{9} aa$.","$\\frac{11}{18} AA + \\frac{4}{18} Aa + \\frac{3}{18} aa$.","$\\frac{5}{10} AA + \\frac{2}{10} Aa + \\frac{3}{10} aa$.","$\\frac{1}{2} AA + \\frac{2}{9} Aa + \\frac{5}{18} aa$."],"ans":0,"exp":"$F_1$ thu được $0.4 AA + 0.4 Aa + 0.2 aa$. Khi $F_1$ tạo hạt sang $F_2$, trọng số sinh sản của $F_1$ là $0.4(1) AA : 0.4(1) Aa : 0.2(0.5) aa \\Rightarrow$ tổng $0.9$. Suy ra $F_2$ có $AA = \\frac{0.4+0.1}{0.9} = \\frac{5}{9}$, $Aa = \\frac{0.2}{0.9} = \\frac{2}{9}$, $aa = \\frac{0.1+0.1}{0.9} = \\frac{2}{9}$."},{"id":"MCQ-PO-143","topic":"population","level":"hsg","levelText":"🔴 HSG Tỉnh","subtopic":"Tác động kết hợp 2 nhân tố: Đột biến & Ngẫu phối","q":"Trong một quần thể ngẫu phối rất lớn ban đầu có $p_0(A) = 0.8$, $q_0(a) = 0.2$. Giả sử chỉ xảy ra đột biến thuận $A \\rightarrow a$ với tần số đột biến cực lớn giả định $u = 0.05$ mỗi thế hệ (đột biến nghịch bằng $0$, không chọn lọc). Sau $2$ thế hệ chịu đột biến thuận, tần số alen $A$ còn lại là:","opts":["$0.720$.","$0.722$.","$0.700$.","$0.760$."],"ans":1,"exp":"Mỗi thế hệ tần số $A$ bị giảm theo cấp số nhân: $p_{n} = p_0 (1 - u)^n$. Sau $2$ thế hệ: $p_2 = 0.8 \\times (1 - 0.05)^2 = 0.8 \\times 0.9025 = 0.722$."},{"id":"MCQ-PO-144","topic":"population","level":"hsg","levelText":"🔴 HSG Tỉnh","subtopic":"Đột biến hai chiều Thuận - Nghịch cân bằng","q":"Xét một gen có $2$ alen $A$ và $a$ chỉ chịu tác động của đột biến $2$ chiều: tốc độ đột biến thuận $A \\rightarrow a$ là $u = 6 \\times 10^{-5}$, tốc độ đột biến nghịch $a \\rightarrow A$ là $v = 2 \\times 10^{-5}$. Khi quần thể đạt trạng thái cân bằng giữa 2 chiều đột biến (không có các nhân tố khác), tần số alen $A$ ($\\hat{p}$) và $a$ ($\\hat{q}$) bằng:","opts":["$\\hat{p} = 0.67$ và $\\hat{q} = 0.33$.","$\\hat{p} = 0.50$ và $\\hat{q} = 0.50$.","$\\hat{p} = 0.25$ và $\\hat{q} = 0.75$.","$\\hat{p} = 0.75$ và $\\hat{q} = 0.25$."],"ans":2,"exp":"Tại cân bằng: lượng chuyển $p u = q v$. Suy ra $\\hat{q} = \\frac{u}{u + v} = \\frac{6}{6 + 2} = 0.75$, và $\\hat{p} = \\frac{v}{u + v} = 0.25$."},{"id":"MCQ-PO-145","topic":"population","level":"hsg","levelText":"🔴 HSG Tỉnh","subtopic":"Cơ sở Toán học Chọn lọc trên Thể Tự thụ","q":"Một quần thể thực vật tự thụ phấn xuất phát ở $P$ gồm $100\\%$ cây dị hợp $Aa$. Không có đột biến, nhưng cứ mỗi hạt có kiểu gen đồng hợp lặn $aa$ bị chết $100\\%$ trước khi trưởng thành. Tỉ lệ cây dị hợp $Aa$ trong tổng số các cây trưởng thành sống sót ở thế hệ $F_n$ tuân theo công thức quy nạp nào?","opts":["$f(Aa)_{F_n} = \\frac{1}{n + 1}$.","$f(Aa)_{F_n} = \\frac{2}{2^n + 1}$.","$f(Aa)_{F_n} = \\frac{2}{2^n - 1}$.","$f(Aa)_{F_n} = \\frac{1}{2^n}$."],"ans":1,"exp":"Kiểm tra: ở $P$ ($n=0$): $\\frac{2}{1+1}=1$ (100% $Aa$); ở $F_1$ ($n=1$): hợp tử $1/4 AA : 1/2 Aa : 1/4 aa$ bỏ $aa$ còn $1/3 AA : 2/3 Aa = \\frac{2}{2^1+1}$; ở $F_2$ ($n=2$): từ $1/3 AA + 2/3 Aa$ tự thụ cho $1/2 AA + 1/3 Aa + 1/6 aa$ bỏ $aa$ còn $3/5 AA + 2/5 Aa = \\frac{2}{2^2+1}$! Công thức chính xác tuyệt đối!"},{"id":"MCQ-PO-146","topic":"population","level":"hsg","levelText":"🔴 HSG Tỉnh","subtopic":"Ứng dụng Công thức $F_n$ Tự thụ loại lặn","q":"Áp dụng quy luật ở câu trên (quần thể khởi đầu $100\\% Aa$ tự thụ phấn liên tiếp, cây $aa$ luôn chết trước sinh sản), đến thế hệ $F_4$, tỉ lệ cây ĐỒNG HỢP TRỘI $AA$ trong các cây trưởng thành là bao nhiêu?","opts":["$\\frac{15}{17}$ ($\\approx 88.24\\%$).","$\\frac{31}{33}$ ($\\approx 93.94\\%$).","$\\frac{7}{9}$ ($\\approx 77.78\\%$).","$\\frac{1}{16}$ ($6.25\\%$)."],"ans":0,"exp":"Ở thế hệ $F_4$ ($n=4$): tỉ lệ $Aa = \\frac{2}{2^4 + 1} = \\frac{2}{17}$. Vì không còn cây $aa$ trưởng thành nên $AA = 1 - \\frac{2}{17} = \\frac{15}{17}$."},{"id":"MCQ-PO-147","topic":"population","level":"hsg","levelText":"🔴 HSG Tỉnh","subtopic":"Tương tác Hardy-Weinberg & Di truyền Chéo","q":"Ở một loài động vật, con đực $XY$, con cái $XX$. Gen lặn $a$ trên NST X (vùng không tương đồng) làm chết $100\\%$ phôi mang kiểu gen $X^a Y$ hoặc $X^a X^a$ ở giai đoạn sớm; phôi $X^A X^a$ phát triển thành cái bình thường. Trong một quần thể ở $P$ có $80\\% X^A X^A + 20\\% X^A X^a$ ở giới cái và $100\\% X^A Y$ ở giới đực. Khi giao phối ngẫu nhiên, tỉ lệ phôi bị chết ở $F_1$ và tỉ lệ giới tính con cái:con đực sống sót ở $F_1$ lần lượt là:","opts":["Phôi chết $5\\%$; tỉ lệ cái : đực sống sót $= 10 : 9$.","Phôi chết $20\\%$; tỉ lệ cái : đực sống sót $= 11 : 9$.","Phôi chết $2.5\\%$; tỉ lệ cái : đực sống sót $= 2 : 1$.","Phôi chết $10\\%$; tỉ lệ cái : đực sống sót $= 1 : 1$."],"ans":0,"exp":"Giới cái tạo trứng: $0.9 X^A : 0.1 X^a$. Giới đực tạo tinh trùng: $0.5 X^A : 0.5 Y$. Hợp tử $F_1$: $0.45 X^A X^A$ (sống), $0.05 X^A X^a$ (sống), $0.45 X^A Y$ (sống), $0.05 X^a Y$ (chết). Tổng chết $= 5\\%$. Số sống: $0.50$ cái : $0.45$ đực $= 10 : 9$!"},{"id":"MCQ-PO-148","topic":"population","level":"hsg","levelText":"🔴 HSG Tỉnh","subtopic":"Liên kết Sinh thái & Đa dạng Loài","q":"Sự phân hóa hình dạng mỏ rất đa dạng ở $14$ loài chim sẻ trên quần đảo Galápagos từ một loài sẻ ăn hạt tổ tiên từ lục địa Nam Mỹ bay tới là minh họa kinh điển cho quá trình tiến hóa nào?","opts":["Phân ly thích nghi (Adaptive radiation) kết hợp cách ly địa lý giữa các đảo và chuyên hóa nguồn thức ăn.","Tiến hóa đồng quy từ nhiều tổ tiên khác hẳn nhau.","Giao phối ngẫu nhiên hòa trộn tất cả các loài thành một loài duy nhất.","Thoái hóa toàn bộ cơ quan tiêu hóa do ăn giống nhau."],"ans":0,"exp":"Các đảo có ổ sinh thái thức ăn khác nhau (hạt cứng, xương rồng, côn trùng) cùng cách ly địa lý giữa các đảo đã thúc đẩy phân ly thích nghi tạo $14$ loài đặc hữu."},{"id":"MCQ-PO-149","topic":"population","level":"hsg","levelText":"🔴 HSG Tỉnh","subtopic":"Cân bằng Liên kết với Gen Phân ly độc lập","q":"Một quần thể động vật giao phối ngẫu nhiên xuất phát ở $P$ gồm $50\\% AABB$ và $50\\% aabb$ ($2$ cặp gen $A/a$ và $B/b$ nằm trên $2$ cặp NST thường khác nhau). Xét tần số giao tử $\\underline{AB}$ mà quần thể tạo ra ở các thế hệ tiếp theo, nhận định nào sau đây là chính xác?","opts":["Toàn bộ cấu trúc $9$ kiểu gen của $2$ locus đạt trạng thái cân bằng tuyệt đối ngay lập tức ở thế hệ $F_1$.","Trong $F_1$, tỉ lệ cá thể mang kiểu gen $AABB$ bằng $0.0625$ ($6.25\\%$).","Tần số alen $A$ tăng dần lên $0.75$ khi giao phối tự do.","Từng gen $A/a$ và $B/b$ đạt tỉ lệ riêng biệt $0.25:0.50:0.25$ ngay ở $F_1$, nhưng tổ hợp kiểu gen $2$ locus chỉ TIỆM CẬN dần về cân bằng liên kết ($D_n = \\frac{0.25}{2^n} \\rightarrow 0$) qua nhiều thế hệ chứ chưa cân bằng tổ hợp ngay tại $F_1$."],"ans":3,"exp":"Ở $P$ tạo $0.5 \\underline{AB} : 0.5 \\underline{ab}$ nên $F_1$ chỉ có $0.25 AABB : 0.50 AaBb : 0.25 aabb$ (không có $AAbb, aaBB$, rõ ràng chưa cân bằng $2$ locus!). Thế hệ $F_1$ có $50\\% AaBb$ tái tổ hợp tạo ra $0.375 \\underline{AB} : 0.125 \\underline{Ab} : 0.125 \\underline{aB} : 0.375 \\underline{ab}$ ($D_1 = 0.125$), giảm một nửa mỗi thế hệ ($D_n \\rightarrow 0$)."},{"id":"MCQ-PO-150","topic":"population","level":"hsg","levelText":"🔴 HSG Tỉnh","subtopic":"Tương tác Quần thể & Phả hệ Đa alen","q":"Xét quần thể người cân bằng về hệ nhóm máu ABO với tần số các alen $p(I^A) = 0.2$, $q(I^B) = 0.3$, $r(I^O) = 0.5$. Một cặp vợ chồng đều có nhóm máu A kết hôn ngẫu nhiên trong quần thể. Xác suất để họ sinh được một người con mang nhóm máu O ($I^O I^O$) là bao nhiêu?","opts":["$\\frac{25}{144}$ ($\\approx 17.36\\%$).","$\\frac{25}{196}$ ($\\approx 12.76\\%$).","$\\frac{1}{9}$ ($\\approx 11.11\\%$).","$\\frac{1}{4}$ ($25.00\\%$)."],"ans":0,"exp":"Nhóm máu A trong quần thể gồm $I^A I^A = p^2 = 0.04$ và $I^A I^O = 2pr = 2(0.2)(0.5) = 0.20$, tổng $= 0.24$. Xác suất $1$ người nhóm máu A mang kiểu gen dị hợp $I^A I^O$ là $\\frac{0.20}{0.24} = \\frac{5}{6}$. Xác suất cả hai vợ chồng là $I^A I^O$ và sinh con $I^O I^O = \\frac{5}{6} \\times \\frac{5}{6} \\times \\frac{1}{4} = \\frac{25}{144}$."}];
